D.books=[
{id:'b1',name:'必修第一册',short:'必修一',desc:'集合、函数与三角：先看懂变化的语言。',stage:'从这里打基础',pdf:'./books/必修第一册.pdf',offset:5,cover:'./assets/book-cover.png',chapters:[1,2,3,4,5]},
{id:'b2',name:'必修第二册',short:'必修二',desc:'向量、空间、统计与概率：把关系画出来。',stage:'把基础用到新问题',pdf:'./books/必修第二册.pdf',offset:5,cover:'./assets/必修第二册-cover.png',chapters:[6,7,8,9,10]},
{id:'e1',name:'选择性必修第一册',short:'选择性必修一',desc:'空间向量和解析几何：用坐标解开图形。',stage:'从图形走向方程',pdf:'./books/选择性必修第一册.pdf',offset:5,cover:'./assets/选择性必修第一册-cover.png',chapters:[11,12,13]},
{id:'e2',name:'选择性必修第二册',short:'选择性必修二',desc:'数列与导数：看见规律，也看见变化快慢。',stage:'理解连续与离散的变化',pdf:'./books/选择性必修第二册.pdf',offset:5,cover:'./assets/选择性必修第二册-cover.png',chapters:[14,15]},
{id:'e3',name:'选择性必修第三册',short:'选择性必修三',desc:'计数、分布与统计：让随机变得有迹可循。',stage:'用数据与概率作判断',pdf:'./books/选择性必修第三册.pdf',offset:5,cover:'./assets/选择性必修第三册-cover.png',chapters:[16,17,18]}
];
D.chapters.forEach(c=>{c.bookId='b1';c.number=c.id;});D.lessons.forEach(l=>{l.bookId='b1';l.chapterId=+l.id.split('.')[0];l.code=l.id;});
const colors=['#368c73','#b17838','#6376b5','#a66d83','#368b9b'];
function chapter(id,number,bookId,title,short,desc,icon){D.chapters.push({id,number,bookId,title,short,desc,icon,color:colors[(id-1)%5],pages:[1,1]});}
chapter(6,6,'b2','平面向量及其应用','用箭头描述关系','方向与大小，合在一个箭头里。','↗');chapter(7,7,'b2','复数','给数多一条方向','走出实数轴，进入复平面。','i');chapter(8,8,'b2','立体几何初步','把空间看清楚','形状、位置与距离，从图走向理由。','◇');chapter(9,9,'b2','统计','从样本看整体','抽得合理，再谈平均与波动。','▥');chapter(10,10,'b2','概率','给不确定性一个数','事件、独立与频率，分开想清楚。','⚄');
chapter(11,1,'e1','空间向量与立体几何','用坐标打开空间','把线、面、角和距离变成向量问题。','↗');chapter(12,2,'e1','直线和圆的方程','图形也有地址','斜率、方程与距离，互相翻译。','○');chapter(13,3,'e1','圆锥曲线的方程','三种有规律的曲线','先问点怎么走，再写椭圆、双曲线与抛物线。','∩');
chapter(14,4,'e2','数列','发现一串数的规则','看第几项，也看前几项加起来。','⋯');chapter(15,5,'e2','一元函数的导数及其应用','抓住瞬间的变化','切线斜率，帮助寻找增减与最值。','ƒ′');
chapter(16,6,'e3','计数原理','把可能数清楚','分类相加，分步相乘，分清顺序。','!');chapter(17,7,'e3','随机变量及其分布','看随机结果的全貌','从一个概率，走向一整张分布表。','∿');chapter(18,8,'e3','成对数据的统计分析','从数据里找联系','画散点、拟合直线，再判断证据强弱。','⋰');
function add(bookId,chapterId,code,title,tag,story,need,panels,examples,quiz,lab,mission,extra=[]){const id=bookId==='b2'?code:bookId+'-'+code;D.lessons.push({id,bookId,chapterId,code,title,tag,story,need,panels,examples,quiz,lab,mission,extra,pages:[1,1],minutes:12+panels.length*2});}
const Q=(q,o,a,h,e)=>({q,o,a,h,e});
add('b2',6,'6.1','平面向量的概念','箭头既告诉你多远，也告诉你往哪儿','向东走3米和向西走3米，路程一样，位置变化却相反。一个箭头能把这两件事一起记下来。','长度、方向、平移。',[
['数量与向量','温度、质量通常只用一个数就能描述；位移、力还要说方向。既有大小又有方向的量叫向量。用有向线段表示时，线段长度代表大小，箭头代表方向。',r`\vec a=\overrightarrow{AB},\quad|\vec a|=AB`],
['起点可以搬，方向长度不变','本册主要研究自由向量。把整个箭头平移到别处，只要长度与方向都不变，仍是相等的向量。不能只比较两个端点的位置。',''],
['零向量与单位向量','大小为0的向量叫零向量，方向可作任意约定；大小为1的向量叫单位向量。单位向量可以朝不同方向，所以并不是同一个向量。',r`|\vec0|=0,\quad |\vec e|=1`],
['相等、相反、平行','长度相同且方向相同才相等；长度相同且方向相反是相反向量。方向相同或相反叫平行向量，也叫共线向量；线段未必真的画在同一条直线上。约定零向量与任意向量平行。',r`\vec b=-\vec a\Rightarrow|\vec b|=|\vec a|`]
],[['向东3米与向北3米相等吗？',['两个箭头都长3米，模相等。','方向一个向东、一个向北，不相同。','所以向量不相等；“模相等”不能推出“向量相等”。']],['把一个向东2米的箭头搬到另一处',['平移不会改变长度和方向。','新的箭头仍向东2米，与原向量相等。','若把箭头倒过来，它就变成相反向量。']]],[Q('两个非零向量相等，需要？',['只有长度相同','只有方向相同','长度和方向都相同'],2,'比较大小和方向两件事。','二者都相同才是相等向量。'),Q('零向量的模是？',['0','1','无定义'],0,'没有位移时长度是多少？','零向量的大小为0。'),Q('向东5米与向西5米是？',['相等向量','相反向量','单位向量'],1,'长度相等，方向相反。','相反向量的和是零向量。'),Q('所有单位向量一定相等吗？',['一定','不一定，方向可能不同','都等于零向量'],1,'单位只限制长度。','单位向量大小都为1，但方向可以不同。')],'vectors2d','改变两根箭头的坐标，做出一对相等向量，再做一对相反向量。');
add('b2',6,'6.2','平面向量的运算','连续走两段，最后移到了哪儿','先向东3米，再向北2米，总位移不是“向东5米”，而是从出发点指向终点的斜箭头。','向量的模与方向；正负数。',[
['加法：首尾相接','把第二个箭头的起点接到第一个的终点，总箭头从第一个起点指向最后终点。这叫三角形法则。同起点时也可补成平行四边形，对角线就是和。',r`\overrightarrow{AB}+\overrightarrow{BC}=\overrightarrow{AC}`],
['运算顺序可以调整','向量加法满足交换律、结合律。和零向量相加不变；与相反向量相加得到零向量。走一个封闭三角形，总位移是0。',r`\vec a+\vec b=\vec b+\vec a,\quad\vec a+(-\vec a)=\vec0`],
['减法：加上反方向','a−b就是a+(−b)。若把a、b起点放在同一点，则a−b从b的终点指向a的终点。顺序倒过来，箭头会反向。',r`\overrightarrow{OB}-\overrightarrow{OA}=\overrightarrow{AB}`],
['数乘：伸缩与掉头','λa的大小为|λ|·|a|。λ>0方向不变，λ<0方向反向，λ=0得到零向量。注意λa是向量，|λa|才是一个非负数。',r`|\lambda\vec a|=|\lambda|\,|\vec a|`],
['分配律帮助化简','数乘能对向量加法分配，系数也能合并。把向量当成可合并的箭头项，但别忘了结果仍有方向。',r`\lambda(\vec a+\vec b)=\lambda\vec a+\lambda\vec b`],
['共线的代数判断','若a≠0，b与a共线，当且仅当存在实数λ使b=λa。零向量这项限制不能漏；若a=0，并非任何非零b都能写成λa。',r`\vec b\parallel\vec a\ (\vec a\ne0)\iff\vec b=\lambda\vec a`],
['中点与长度','M是AB中点时，OM=(OA+OB)/2。一般|a+b|≤|a|+|b|，只有方向相同等特殊情况才取等；位移大小不必等于总路程。',r`\overrightarrow{OM}=\frac{\overrightarrow{OA}+\overrightarrow{OB}}2`]
],[['走东3米，再走北4米',['把两个箭头首尾相接，和箭头连接起点和终点。','两段互相垂直，由勾股定理总位移大小√(3²+4²)=5米。','总路程7米，总位移大小5米，描述的是不同的量。']],['化简 2(a+b)−(3a−b)',['先展开：2a+2b−3a+b。','合并a项得−a，合并b项得3b。','结果−a+3b。减括号时每一项都要变号。']]],[Q('AB向量+BC向量等于？',['AC向量','CA向量','BA向量'],0,'从A走到B再到C。','总位移是从A到C。'),Q('若a的模为3，则−2a的模？',['−6','6','1'],1,'模不能为负。','|−2a|=2|a|=6。'),Q('同起点向量a−b的箭头从哪到哪？',['a终点到b终点','b终点到a终点','原点到任意处'],1,'减去谁就从谁的终点出发。','差向量从b终点指向a终点。'),Q('a≠0，b=−3a，则a、b？',['垂直','方向相同','方向相反且共线'],2,'负数乘让箭头掉头。','b长度为a的3倍，方向相反。')],'vectors2d','看和向量与差向量如何变化。让两向量垂直，再比较总路程与总位移。');
add('b2',6,'6.3','平面向量基本定理及坐标表示','给箭头装上横向和纵向分量','从学校走到图书馆，可以拆成向东多少、向北多少。坐标让箭头不用反复搬来搬去，也能计算。','坐标；向量加减与数乘；余弦。',[
['两根不共线的箭头足够','平面里任取两个不共线向量e₁、e₂，每个平面向量都能唯一写成λ₁e₁+λ₂e₂。它们叫一组基底；若两根共线，就铺不开整个平面。',r`\vec a=\lambda_1\vec e_1+\lambda_2\vec e_2`],
['直角坐标是特别方便的一组基底','取互相垂直的单位向量i、j，则a=xi+yj，记作(x,y)。起点A(x₁,y₁)、终点B(x₂,y₂)，位移坐标是终点减起点。',r`\overrightarrow{AB}=(x_2-x_1,y_2-y_1)`],
['坐标逐项算','加减分别算横纵分量，数乘让每个分量都乘系数。两向量平行可用x₁y₂−x₂y₁=0判断；这能避免直接除以某个可能为0的分量。',r`(x_1,y_1)+(x_2,y_2)=(x_1+x_2,y_1+y_2)`],
['数量积：看沿同一方向的配合程度','两个非零向量夹角取[0,π]。数量积是|a||b|cosθ，是一个数，不是新箭头。锐角时为正、直角为0、钝角为负；它也描述力沿位移方向做的功。',r`\vec a\cdot\vec b=|\vec a||\vec b|\cos\theta`],
['数量积的坐标形式','在直角坐标中，把同方向分量相乘再相加。a·a=|a|²，可求长度；两个非零向量垂直当且仅当数量积为0。数量积对加法分配，但不能像普通乘法那样随意交换括号。',r`\vec a\cdot\vec b=x_1x_2+y_1y_2,\quad |\vec a|=\sqrt{x^2+y^2}`],
['求夹角，先算三个数','先求数量积，再分别求两个模，最后代入余弦比值。若向量为零，夹角没有按通常方式定义，不能直接除以0。',r`\cos\theta=\frac{\vec a\cdot\vec b}{|\vec a||\vec b|}`]
],[['a=(1,2)，b=(3,−1)，求和与数量积',['和为(1+3,2−1)=(4,1)。','数量积1×3+2×(−1)=1。','数量积是正数，说明两非零向量夹角是锐角。']],['A(1,2)、B(4,6)，求AB的长度',['终点减起点，AB向量=(3,4)。','模=√(3²+4²)=5。','不能把两个点的坐标相加来当位移。']]],[Q('从A(2,1)到B(5,−1)的向量是？',['(7,0)','(3,−2)','(−3,2)'],1,'终点减起点。','(5−2,−1−1)=(3,−2)。'),Q('(1,2)·(2,−1)等于？',['0','4','(2,−2)'],0,'对应分量相乘再相加。','1×2+2×(−1)=0，因此这两个非零向量垂直。'),Q('平面基底的两个向量必须？',['长度相同','不共线','都沿x轴'],1,'需要能够铺开整个平面。','共线箭头只能铺出一条线。'),Q('向量(3,4)的模是？',['7','25','5'],2,'使用勾股定理。','√(9+16)=5。')],'vectors2d','调整两向量，使数量积等于0。观察它们是否垂直，并核对分量乘积。');
add('b2',6,'6.4','平面向量的应用','把三角形和实际问题翻译成箭头','测不到河对岸的长度时，可以测角、测已知边，再利用三角形关系。向量也能帮你证明平行和垂直。','向量数量积；三角函数；三角形内角和。',[
['几何证明的路线','先选起点或基底，把待研究的线段写成向量；平行查共线，垂直查数量积为0，相等查坐标或模。最后把代数结论翻译回原图。',''],
['余弦定理：两边夹角，求第三边','三角形中a、b、c分别对A、B、C。由向量差的模平方可推得a²=b²+c²−2bc cosA。直角时cosA=0，就退回勾股定理。',r`a^2=b^2+c^2-2bc\cos A`],
['正弦定理：边与对角配对','同一个三角形中，边长除以对应角的正弦，三个比相同，且等于外接圆直径2R。别把a与B错配。',r`\frac a{\sin A}=\frac b{\sin B}=\frac c{\sin C}=2R`],
['已知两边和一边对角，要防止两解','从sinB算角时，B与π−B正弦相同。要结合三角形内角和与边长条件判断可能有0、1或2个三角形。不能只取计算器给的一个锐角。',''],
['面积与实际测量','已知两边和夹角，面积S=bc sinA/2。解实际题先画图、标边角、选定理，算后检查长度、角度、单位是否合理。',r`S=\frac12bc\sin A`]
],[['两边3、4，夹角60°，第三边多长？',['余弦定理：a²=3²+4²−2×3×4×cos60°。','cos60°=1/2，因此a²=25−12=13。','第三边√13；面积为1/2×3×4×√3/2=3√3。']],['A=30°、B=45°，a=2，求b',['正弦定理：b/sin45°=2/sin30°。','b=2×(√2/2)/(1/2)。','得到b=2√2。']]],[Q('三角形两边a,b与夹角C已知，第三边平方是？',['a²+b²−2ab cosC','a²+b²+2ab cosC','2ab sinC'],0,'直角时应退回勾股定理。','余弦定理给c²=a²+b²−2ab cosC。'),Q('a/sinA与b/sinB有什么关系？',['相等','互为倒数','总差1'],0,'同一个三角形应用正弦定理。','边与对应角的正弦之比相同。'),Q('两边为2、3，夹角90°，面积是？',['6','3','√13'],1,'面积=两边乘积乘夹角正弦的一半。','1/2×2×3×1=3。'),Q('sinB=1/2，三角形内角B可能先考虑？',['只有30°','30°或150°再检查','只有210°'],1,'三角形内角在0°到180°之间。','30°和150°都满足正弦值，需结合其他条件判断。')],'triangle','改变两边与夹角，核对第三边和面积。把夹角设90°，看余弦定理如何变成勾股定理。');
add('b2',6,'6.M','数学探究：用向量研究三角形','把中线与垂直关系算出来','三角形三条中线为什么会相交在一个点？选好坐标后，重心的位置会直接从三个顶点里算出来。','向量坐标、数量积、中点。',[
['先决定怎样放坐标','把一个顶点放在原点、一条边放在x轴上，通常可以少算很多量。只做平移和转动，不会改变中点、长度与垂直等几何性质。',''],
['中点，取两个端点的平均','若M是BC中点，则M的每个坐标都是B、C对应坐标的平均。这来自BM=MC或OM=(OB+OC)/2。',r`M=\left(\frac{x_B+x_C}2,\frac{y_B+y_C}2\right)`],
['重心，取三个顶点的平均','G=(A+B+C)/3会落在每条中线上，并把中线按2:1分开，靠顶点的那一段更长。可通过AG=(2/3)AM直接验证。',r`G=\left(\frac{x_A+x_B+x_C}3,\frac{y_A+y_B+y_C}3\right)`],
['垂直仍查数量积','研究高线时，取高线的方向向量与对应边做数量积。先提出猜想，再用向量验证；数值图形帮助发现，但完整证明要覆盖任意满足条件的三角形。','']
],[['A(0,0)、B(6,0)、C(0,3)，求重心',['三个横坐标平均：(0+6+0)/3=2。','三个纵坐标平均：(0+0+3)/3=1。','G=(2,1)。BC中点M=(3,1.5)，AG恰为AM的2/3。']],['验证从A到BC中点的线段是中线',['先由端点平均求M。','中线的定义是连接顶点与对边中点。','再检查向量AG=(2/3)AM，就能验证G落在该中线上。']]],[Q('三角形重心坐标是三个顶点坐标的？',['和','平均','乘积'],1,'三条中线共享这个点。','对应坐标相加除以3。'),Q('重心把中线分成AG:GM为？',['1:1','1:2','2:1'],2,'靠近顶点的那段更长。','AG占整条中线的2/3。'),Q('B(2,0)、C(6,4)的中点？',['(4,2)','(8,4)','(2,2)'],0,'分别求横纵坐标平均。','((2+6)/2,(0+4)/2)=(4,2)。'),Q('图形看上去垂直，怎样进一步验证？',['只凭外观','算两个方向向量数量积是否0','看颜色'],1,'用能计算的条件替代视觉猜测。','非零方向向量数量积为0，等价于垂直。')],'triangle','观察三角形的中线与重心，改变形状后检验重心是否仍把中线按2:1分开。');
add('b2',7,'7.1','复数的概念','给数轴再加一个方向','在实数范围里，x²=−1没有解。引入一个平方为−1的新数i，就能把这类问题继续算下去。','实数；平方；平面坐标。',[
['i是一个新单位','规定i²=−1。形如a+bi的数叫复数，a、b都是实数；a是实部，b是虚部。虚部是实数b，不是bi。',r`z=a+bi,\quad i^2=-1`],
['实数与纯虚数','b=0时是实数；a=0且b≠0时是纯虚数。0既是实数，也可写成0+0i，但不称纯虚数。所有复数组成复数集C，实数集R包含在其中。',''],
['相等，分别对实部与虚部','两个复数相等，当且仅当实部分别相等、虚部分别相等。复数一般没有实数那样的大小顺序，所以不能随意比较1+i与2+i谁“大”。',r`a+bi=c+di\iff a=c,\ b=d`],
['复平面与模','把a+bi放在点(a,b)，横轴为实轴，纵轴为虚轴。它也对应从原点出发的向量。模是到原点的距离，等于√(a²+b²)。',r`|z|=\sqrt{a^2+b^2}`],
['共轭：沿实轴照镜子','a+bi的共轭复数为a−bi。两个点关于实轴对称，模相同。实数的共轭就是它本身。',r`\overline z=a-bi`]
],[['z=3−4i，读出实部、虚部与模',['实部3，虚部−4。','复平面对应(3,−4)。','模√(3²+(−4)²)=5，共轭为3+4i。']],['a+2i=3+bi，求a,b',['复数相等，实部对应相等，a=3。','虚部对应相等，b=2。','不是把i当成普通未知数移项后再除掉。']]],[Q('2−3i的虚部是？',['−3','−3i','2'],0,'虚部是i的实数系数。','实部2，虚部−3。'),Q('i²等于？',['1','−1','i'],1,'这是引入i的规定。','i²=−1。'),Q('3+4i的模？',['7','25','5'],2,'到原点的距离。','√(3²+4²)=5。'),Q('1+2i的共轭？',['−1−2i','1−2i','−1+2i'],1,'只改变虚部符号。','关于实轴对称，实部不变。')],'complex','拖动复平面中的点，读出实部、虚部和模，再看共轭点的镜像位置。');
add('b2',7,'7.2','复数的四则运算','把i²换成−1，就能继续算','复数相加像坐标相加；相乘先像多项式展开，再把出现的i²换成−1。除法要让分母变成实数。','复数定义；分配律；共轭。',[
['加减：同类项合并','实部与实部算，虚部与虚部算。复平面上加法仍可用平行四边形法则；减法对应两个点之间的位移。',r`(a+bi)+(c+di)=(a+c)+(b+d)i`],
['乘法：先展开，再化简','逐项相乘得到ac+adi+bci+bdi²，最后用i²=−1整理。别把i²漏掉，也别把它当1。',r`(a+bi)(c+di)=(ac-bd)+(ad+bc)i`],
['i的幂，每4次一循环','i、−1、−i、1，之后重复。指数除以4看余数，就能快速确定高次幂。',r`i^1=i,\ i^2=-1,\ i^3=-i,\ i^4=1`],
['除法：分母乘它的共轭','分子分母同时乘c−di，分母变成c²+d²。当分母复数不为0时，这个实数为正，因此可以相除。',r`\frac{a+bi}{c+di}=\frac{(a+bi)(c-di)}{c^2+d^2}`],
['模与乘除的联系','乘积的模等于模的乘积，商的模等于模的商。z与共轭相乘等于|z|²，可帮助检查计算结果。',r`z\overline z=|z|^2,\quad |z_1z_2|=|z_1||z_2|`]
],[['算(1+i)²',['展开为1+2i+i²。','用i²=−1，实部1与−1抵消。','结果2i。不是1+i²=0，因为还存在中间项。']],['算(1+i)/(1−i)',['分子分母同乘1+i。','分母(1−i)(1+i)=2，分子(1+i)²=2i。','结果i；可用i(1−i)=1+i核对。']]],[Q('(2+i)+(1−3i)等于？',['3−2i','3+4i','1+4i'],0,'实部相加，虚部相加。','2+1=3，1−3=−2。'),Q('(1+i)²等于？',['0','2i','2'],1,'别忘了2i这一项。','1+2i+i²=2i。'),Q('i的2026次方是？',['1','i','−1'],2,'2026除以4余2。','i的幂每4次循环，余2对应−1。'),Q('(3+2i)(3−2i)等于？',['5','13','9−4i'],1,'一个复数乘共轭得到模平方。','3²+2²=13。')],'complex','比较复数与共轭的乘积，核对分母为什么能变成一个正实数。');
add('b2',7,'7.3','★ 复数的三角表示','同一个点，换成距离和角度来描述','除了向右多少、向上多少，还可以说：离原点多远，朝哪个角度。两种方式描述的是同一个复数。','复平面；单位圆与三角函数。',[
['非零复数的模与辐角','设模r>0，向量与实轴正向的角为θ，则横坐标r cosθ，纵坐标r sinθ。θ可以加上2kπ，表示同一个终边；零复数没有确定的辐角。',r`z=r(\cos\theta+i\sin\theta)`],
['代数形式与三角形式互换','从a+bi先算r=√(a²+b²)，再由cosθ=a/r、sinθ=b/r并结合象限找角。不能只看tanθ=b/a就忽略象限或a=0。',''],
['乘法：模相乘，角相加','两式相乘后使用三角和角公式，可知结果的模相乘、辐角相加。这也解释了乘i相当于逆时针旋转90°。',r`z_1z_2=r_1r_2[\cos(\theta_1+\theta_2)+i\sin(\theta_1+\theta_2)]`],
['除法：模相除，角相减','分母非零时，商的模是r₁/r₂，辐角是θ₁−θ₂。反复相乘还能得到棣莫弗公式，但要先熟练掌握一轮乘法与旋转。',r`z_1/z_2=(r_1/r_2)[\cos(\theta_1-\theta_2)+i\sin(\theta_1-\theta_2)]`]
],[['把1+i写成三角形式',['模r=√2，点在第一象限。','横纵分量相等，所以θ=π/4。','1+i=√2(cosπ/4+i sinπ/4)。']],['把1+i乘i，在平面上发生什么？',['代数计算：i(1+i)=−1+i。','从点(1,1)到(−1,1)，模仍为√2。','角从π/4变为3π/4，逆时针转了π/2。']]],[Q('非零复数的辐角可以相差？',['任意实数','2kπ，k为整数','只有0'],1,'终边转整圈后回到原位。','同一复数有相差2kπ的辐角。'),Q('乘以i对应怎样的旋转？',['顺时针90°','逆时针90°','180°'],1,'i的模为1，角为π/2。','模不变，辐角增加π/2。'),Q('复数相乘时，模怎样变化？',['相加','相乘','相减'],1,'将三角形式相乘看系数。','模变成r₁r₂。'),Q('零复数有没有确定辐角？',['有，为0','有，为π','没有'],2,'零向量没有一个确定方向。','模为0时，角无法确定。')],'polar','改变模与辐角，比较直角坐标与三角表示；再试着转过一整圈。');
add('b2',8,'8.1','基本立体图形','先认清每个面，再想整个空间','纸盒、帐篷、漏斗和球，外形不同，但可以按面、棱、顶点和旋转方式分类。','平面多边形、圆、垂直。',[
['多面体与旋转体','由平面多边形围成的几何体叫多面体；由平面图形绕同平面内直线旋转形成的几何体常叫旋转体。观察时找出底面、侧面、轴和高。',''],
['棱柱：两底平行且全等','棱柱的两个底面是平行全等多边形，侧面都是平行四边形，各侧棱平行且相等。侧棱垂直底面的叫直棱柱；斜棱柱的高与侧棱长可能不同。',''],
['棱锥与棱台','棱锥只有一个多边形底面，侧面是有公共顶点的三角形。平行底面的平面截棱锥，截去小棱锥后剩下棱台。正棱锥底面为正多边形，顶点投影在底面中心。',''],
['圆柱、圆锥、圆台','矩形绕一边旋转成圆柱，直角三角形绕一直角边旋转成圆锥，直角梯形绕垂直底边的腰旋转成圆台。母线是侧面上沿生成方向的线段，圆锥母线不是高。',''],
['球与简单组合体','半圆绕直径旋转得到球；球面上各点到球心距离都等于半径。组合体可用“加上几块”或“挖去几块”理解，接合处的面不一定属于外表面。','']
],[['圆锥底面半径3、高4，母线多长？',['取过轴的截面，半径、高、母线构成直角三角形。','母线l=√(3²+4²)=5。','高4垂直底面，母线5沿着侧面，不能混用。']],['判断斜着的纸盒是不是棱柱',['先找两个平行全等的底面。','再查侧面是否为平行四边形，侧棱是否平行相等。','侧棱不垂直底面也可能是棱柱，称斜棱柱。']]],[Q('圆锥的母线与高一定相等吗？',['一定','不一定','都为0'],1,'母线沿侧面，高垂直底面。','一般母线长于高，分别是直角三角形斜边与直角边。'),Q('棱柱两个底面必须？',['平行全等','垂直','只需面积相等'],0,'观察上下两个多边形的形状与位置。','平行且全等是棱柱底面的关键特征。'),Q('平行底面截棱锥，去掉顶部后得到？',['棱台','球','棱柱'],0,'上底比下底小，侧面仍有规律。','这是棱台的来源。'),Q('两个立方体接起来，接合面算外表面积吗？',['算两次','算一次','不算'],2,'从外面能看到这个面吗？','接合面在内部，不能继续计入外表面。')],'solids','切换几何体，分别找出底面、高与母线。转动视角，确认被遮住的棱仍然存在。');
add('b2',8,'8.2','立体图形的直观图','纸上的斜线，不等于空间里真是斜的','一张纸只有两个方向，却要表现立体感。斜二测画法用一套约定，把空间坐标压到纸面。','坐标、平行线、长度比例。',[
['先会读三视图','正视图、侧视图、俯视图分别从三个互相垂直方向看物体。相同空间长度在相应视图中要对齐；视图中的重合线段不表示空间里是同一条线。',''],
['斜二测的坐标约定','平面图形先选互相垂直的x、y轴；在纸上把两轴画成45°或135°。平行x轴的线段长度保持，平行y轴的线段长度减半，并保持各自平行关系。',''],
['立体图还要加竖直方向','空间中的高度方向通常画成竖直z轴并保持长度。先画底面，再按高画侧棱、连接顶面；可见轮廓画实线，被遮挡的棱画虚线。',''],
['直观图保持什么，不保持什么','平行关系和同一轴向的比例可以保留；角度和一般长度通常失真。正方形在直观图里像平行四边形，但原图的直角仍然是直角。','']
],[['边长4的正方形怎样画斜二测图？',['沿纸面x′轴画一条长4的边。','另一轴与x′成45°，平行该轴的边只画4/2=2。','补平行线得到平行四边形，它表示原来的正方形。']],['画高3的直四棱柱',['先按斜二测规则画底面。','从底面各顶点竖直向上画长3的线段。','连接顶点并按遮挡标实虚线，不用把高度再减半。']]],[Q('斜二测中，平行y轴且原长6的线段画多长？',['6','3','12'],1,'只有这一轴向的长度减半。','6/2=3。'),Q('原来的直角在直观图里必须仍是90°吗？',['必须','不必，角度可能失真','不允许出现角'],1,'它是按约定投到纸上的图。','直观图通常不保持角度。'),Q('直观图中的虚线一般表示？',['长度为0','被遮住的棱','图画错了'],1,'空间里存在但视线被挡住。','虚线表示不可见的棱或轮廓。'),Q('画高4的竖直棱，通常画多长？',['2','4','8'],1,'z方向通常保持长度。','不用对所有方向一律减半。')],'projection','调整原图的长、宽、高，对照斜二测图，核对哪个方向减半、哪个方向保持。');
add('b2',8,'8.3','简单几何体的表面积与体积','包一层纸和装多少水，是两件事','给罐子贴标签要算面积，问能装多少水要算体积。公式里的高和母线，也各有分工。','平面面积、π、勾股定理。',[
['柱体体积：底面积乘高','棱柱、圆柱都有V=Sh，S为底面积，h是两底面的垂直距离。直棱柱侧面积=底面周长×高；一般斜棱柱不能这样直接用侧棱代高。',r`V_{\text{柱}}=Sh`],
['锥体体积：同底同高柱体的三分之一','棱锥、圆锥都满足V=Sh/3。圆锥S=πr²，所以V=πr²h/3。别把体积里的高换成母线。',r`V_{\text{锥}}=\frac13Sh`],
['台体体积','上、下底面积S₁、S₂且高h，体积为h(S₁+√(S₁S₂)+S₂)/3。圆台代入两个圆的面积，得到πh(r²+rR+R²)/3。',r`V_{\text{台}}=\frac h3(S_1+\sqrt{S_1S_2}+S_2)`],
['侧面展开，再加底面','圆柱侧面展开为长方形，面积2πrh；圆锥侧面展开为扇形，面积πrl；圆台侧面积π(R+r)l。总表面积还要加全部外露底面。',r`S_{\text{圆锥全}}=\pi rl+\pi r^2`],
['球的面积与体积','半径变2倍，面积变4倍，体积变8倍。面积单位是平方，体积单位是立方，数量级也能帮助检查误用公式。',r`S_{\text{球}}=4\pi R^2,\quad V_{\text{球}}=\frac43\pi R^3`],
['组合体，别多算接合面','体积可按分割相加或挖空相减；表面积要重新找外露的面。实心体与空心壳的“装水体积”也不同，读题先确认。','']
],[['圆柱r=2、h=3，体积与表面积？',['底面积4π，体积4π×3=12π。','侧面积2π×2×3=12π。','两底面积共8π，总表面积20π。']],['圆锥r=3、h=4，求全表面积与体积',['母线l=5。侧面积πrl=15π。','底面积9π，总表面积24π。','体积(1/3)×9π×4=12π。']]],[Q('同底同高，锥体体积是柱体的？',['3倍','1/3','1/2'],1,'底与高相同，只比较系数。','柱体Sh，锥体Sh/3。'),Q('球半径变3倍，体积变？',['3倍','9倍','27倍'],2,'体积与半径三次方成正比。','3³=27。'),Q('圆锥侧面积使用哪一个长度？',['母线l','直径2r代替高','只用高h'],0,'侧面展开是扇形。','侧面积πrl，l是母线。'),Q('表面积的单位可以是？',['米','平方米','立方米'],1,'数的是一层面。','面积对应平方单位。')],'surface','切换柱、锥、球并改变尺寸，观察面积和体积放大倍数是否相同。');
add('b2',8,'8.4','空间点、直线、平面之间的位置关系','图上相交，空间里也许没有碰到','桥上道路和桥下道路，投到一张图里可能交叉，实际却不在同一平面。空间判断需要理由。','点、直线、平面；集合语言。',[
['平面是无限延伸的','图上画的平行四边形只是一个平面的局部示意，不是平面边界。线在图形外面画着，也可能仍在这个平面内。',''],
['三个基本事实','不共线三点确定一个平面；直线上两点在平面内，则整条直线在平面内；两个不重合平面若有一个公共点，则有且只有一条过该点的公共直线。',''],
['由基本事实得到的确定方法','一条直线和线外一点、两条相交直线、两条平行直线，都能确定一个平面。证明多点共面时，可以先选其中一些确定平面，再说明其余点也在其中。',''],
['两条直线有三种位置','同一平面内两线可相交或平行；不在任何同一平面内的两线叫异面直线。异面不是“没有画在一起”，而是无法共面。',''],
['直线与平面、平面与平面','直线在平面内、与平面相交、与平面平行；两个不同平面相交于一条直线，或互相平行。无公共点是线面平行的定义特征。',''],
['异面直线夹角','可把其中一条平移到与另一条相交，再取不超过90°的那个角。平移不改方向；空间两直线垂直不一定真的相交，可能是异面垂直。','']
],[['立方体里，底面一条棱与另一方向的竖棱',['若它们有共同顶点，就相交。','若没有共同顶点且方向不同，还需检查是否共面。','例如AB与CC₁既不平行也不相交，是异面直线。']],['为何同一直线上的三个点不能唯一确定平面？',['过这条直线可以转出很多不同平面。','三个点虽然都在这些平面里，却选不出唯一一个。','确定平面的三个点必须不共线。']]],[Q('唯一确定一个平面的三个点必须？',['不共线','都在一条直线上','任意三个重复点'],0,'同一直线上可穿过很多平面。','不共线三点才能确定唯一平面。'),Q('两条异面直线一定？',['相交','平行','不能放在同一平面内'],2,'这是异面的定义。','既不相交也不平行，并且不共面。'),Q('直线两个不同点都在平面内，则？',['整条直线在平面内','只有线段在内','仍无法确定'],0,'使用基本事实。','整条直线都属于该平面。'),Q('两个不同平面相交，它们的交集是？',['一个孤立点','一条直线','一个圆'],1,'公共点会延伸成公共直线。','两不同相交平面的交线是一条直线。')],'space','转动立方体，区分相交、平行、异面。不要把投影图上的交叉当成空间交点。');
add('b2',8,'8.5','空间中的平行关系','找一根桥梁，把线和平面联系起来','要证明一条线不穿过一个面，可以在面里找到一条与它方向相同的线。条件要齐，才推得过去。','空间位置关系；平面确定方法。',[
['线面平行的判定','若直线a不在平面α内，平面内存在直线b且a∥b，则a∥α。必须说明a在面外，否则a也可能就躺在平面里。',''],
['线面平行的性质','若a∥α，过a的平面β与α相交于b，则a∥b。把线面关系变成线线关系，常能接着用平面几何证明。',''],
['面面平行的判定','一个平面内两条相交直线都平行于另一平面，就能推出两平面平行。只找到一条线不够，甚至找到两条平行线也不够撑开一个平面。',''],
['面面平行的性质','两平行平面被第三个平面截得的两条交线平行；一个平面内的直线与另一个平面平行。线、面条件对照清楚，避免把结论倒过来用。',''],
['证明常用中点桥梁','连接三角形两边中点可得中位线，与第三边平行；利用面内的中位线，常能把已知点线信息送到线面或面面判定中。','']
],[['在三角锥中，M、N是AB、AC中点，证明MN∥底面BCD',['三角形ABC中，MN∥BC。','BC在底面BCD内，MN不在该底面内。','根据线面平行判定，MN∥平面BCD。']],['一条面内直线平行另一平面，能推出面面平行吗？',['想象一本打开的书，两页相交于书脊。','一页上仍可有一条线与另一页平行。','所以只有一条不够；需要两条相交直线都平行另一面。']]],[Q('线面平行判定中，所找的平行线应在哪？',['目标平面内','目标平面外任意处','只能和原线重合'],0,'用面内的一条线作桥梁。','再说明原线不在该面内，条件才齐。'),Q('面面平行判定需要面内两条怎样的直线？',['相交','任意两条平行线','同一条重复两遍'],0,'它们要撑开整个平面。','两条相交直线才有足够的方向信息。'),Q('平行平面被第三平面截出的交线？',['平行','一定垂直','异面'],0,'两交线还在同一截面内。','它们互相平行。'),Q('三角形两边中点连线与第三边？',['平行','垂直','相交于中点'],0,'中位线定理。','中位线平行第三边，长度为其一半。')],'parallel','在空间图中寻找面内的平行线，核对原线是否在面外；再比较一个方向与两个相交方向。');
add('b2',8,'8.6','空间中的垂直关系','只垂直一条线，还不能保证垂直整个面','旗杆垂直地面，意味着它与地面里各方向的线都垂直。证明时不必查无穷多条，两条相交方向就够。','直角、空间位置、投影。',[
['线面垂直的定义与判定','一条直线垂直平面内任意直线，就垂直这个平面。判定时只需它垂直面内两条相交直线；这两条不能彼此平行。',''],
['线面垂直的性质','若两条直线都垂直同一平面，则两线平行。若一条线垂直一个平面，则它垂直平面内的每条直线。注意从一条垂线不能随意推出整个面。',''],
['斜线与平面所成角','过斜线上一点向平面作垂线，得到斜线在面内的射影。斜线与射影的锐角是线面角；若垂直面，角为90°；若平行面或在面内，角为0°。',''],
['二面角，先作平面角','两个半平面以交线为公共棱形成二面角。在棱上一点，各半平面内分别作垂直棱的射线，两射线夹角就是它的平面角。不能任取两条斜线就量。',''],
['面面垂直的判定与性质','若一个平面经过另一个平面的垂线，则两平面垂直。反过来，两平面垂直时，在其中一个面内垂直交线的直线，会垂直另一个平面。','']
],[['长方体的竖棱为什么垂直底面？',['竖棱同时垂直从同一顶点出发的两条底棱。','两底棱在底面内且相交。','由线面垂直判定，竖棱垂直底面。']],['斜线段长10，端点到平面距离6，线面角多少？',['把线段、射影、垂线组成直角三角形。','线面角θ的对边是垂距6，斜边10。','sinθ=6/10=0.6，θ≈36.87°。']]],[Q('证明线面垂直，查面内两条线应当？',['相交','平行','可以重合'],0,'需要两个不同方向。','垂直两条相交直线，才能判定垂直整个面。'),Q('两条直线都垂直同一平面，则两线？',['平行','异面','一定相交'],0,'方向都沿这个平面的法向方向。','两直线互相平行。'),Q('线面角是斜线与哪条线的夹角？',['平面交线任意一条','它在平面上的射影','平面内任意一条'],1,'要先作垂足得到射影。','斜线与正射影形成的锐角才是线面角。'),Q('作二面角的平面角，两条射线都必须？',['平行棱','垂直棱','任意选择'],1,'各在对应半平面内，并从棱上同一点出发。','两射线都垂直公共棱。')],'perpendicular','观察垂线、斜线和射影。改变高度，比较线面角与斜线长度如何一起变化。');
add('b2',9,'9.1','随机抽样','想知道全校，不能只问自己班','抽样不是挑方便的人问，而是设计一个尽可能公平、能代表目标总体的取样办法。','比例、随机数、总体与样本。',[
['总体、个体、样本','总体是要研究的全部对象，个体是其中一个对象，样本是实际调查的部分对象。先说清调查目标和范围，再决定抽多少、怎么抽。',''],
['简单随机抽样','把总体中的N个个体编号，用抽签或随机数抽出n个，不放回。每个个体入样机会相等，每个同容量样本被抽到的机会相等。便利抽样不能自动满足这一点。',''],
['分层随机抽样','若不同群体差别明显，先按已知特征分层，再在各层随机抽。按比例分配时nₕ=nNₕ/N；层内仍要随机，不能按主观偏好挑人。',r`n_h=n\frac{N_h}{N}`],
['用样本估计总体，要接受随机波动','同一总体重抽会得到不同样本。扩大样本常能减少随机误差，却修复不了系统性漏掉某一群体的问题。设计代表性比盲目堆人数更重要。','']
],[['全校1000人，其中某年级400人，分层抽100人',['该层占总体400/1000=40%。','按比例分配100×40%=40人。','在这400人内部随机抽40，不能只挑前40名。']],['只在篮球场问同学每周运动时长，有何问题？',['篮球场上的人可能本来就更爱运动。','样本的入选方式与研究变量有关系，会产生偏差。','应回到全校名单随机抽取，或按合理分层设计。']]],[Q('从1000人中简单随机抽50人，每人入选概率？',['1/1000','50/1000','50'],1,'样本人数除总体人数。','每人入样机会相同，为0.05。'),Q('分层抽样后，层内应该？',['继续随机抽','只挑成绩最好的人','只挑方便联系的人'],0,'分层不是取消随机。','层内仍要按随机方法抽取。'),Q('300人和200人两层，共抽50，第一层抽多少？',['20','30','25'],1,'按300/500分配。','50×300/500=30。'),Q('样本很大就一定没有偏差吗？',['一定','不一定，取样方式也重要','不需要总体'],1,'只调查某一类人，再多人也可能偏。','代表性和随机性不能靠人数自动保证。')],'sampling','切换简单随机与分层抽样，多抽几次，比较每层的样本人数及估计值。');
add('b2',9,'9.2','用样本估计总体','平均数只是故事的一部分','两组人的平均分都80，一组人人接近80，另一组有人很高有人很低。只看平均，会丢掉重要信息。','加减乘除；排序；百分比。',[
['先看分布，再选代表数','条形图、扇形图适合分类频数，直方图适合分组连续数据。频率=频数/样本量；频率分布直方图的纵轴为频率/组距，所以每块面积表示这一组频率，总面积1。',''],
['平均数、中位数、众数','平均数使用全部数值，易受极端值影响；中位数先排序，取中间一个或两个的平均；众数是出现最多的值，可能不唯一。要按问题选择，不能总说平均最可靠。',r`\bar x=\frac{x_1+\cdots+x_n}{n}`],
['加权平均与总体均值估计','各组样本量不同，合并平均要按人数加权；分层估计总体均值时按各层总体比例加权。直接把各组平均再平均，只有权重相同时才合适。',r`\bar x=\sum_h w_h\bar x_h,\quad\sum_h w_h=1`],
['百分位数，先排序','本书方法：设p∈(0,100)，算np/100；不是整数时取向上取整位置的数，是整数k时取第k与第k+1个数的平均。百分位反映数据的位置，不是“把某个数乘百分比”。',''],
['方差与标准差，量出分散程度','先算每个值离均值多远，平方后求平均得到方差，再开方得到标准差。本节样本描述用除以n；标准差与原数据同单位，方差单位为平方。',r`s^2=\frac1n\sum_{i=1}^n(x_i-\bar x)^2,\quad s=\sqrt{s^2}`],
['整体平移与放大','每个数都加c，均值加c，方差不变；每个数都乘a，均值乘a，方差乘a²，标准差乘|a|。这也能快速核对单位换算。','']
],[['数据1、2、3、4、10，求平均和中位数',['平均为(1+2+3+4+10)/5=4。','排序已完成，中间第3个数为3，所以中位数3。','极端值10把平均往上拉，但不改变中位数的位置。']],['数据1、2、3，求方差',['均值2。偏差为−1、0、1。','平方相加为1+0+1=2。','除以n=3，方差2/3，标准差√(2/3)。']],['8个数按顺序为1到8，25百分位数是多少？',['算8×25%=2，是整数。','取第2与第3个数的平均。','结果(2+3)/2=2.5。']]],[Q('直方图中每组频率对应矩形的？',['高度总是不需要组距','面积','周长'],1,'纵轴为频率/组距。','面积=组距×频率密度=频率。'),Q('1、2、100的中位数是？',['2','103/3','100'],0,'排序后取中间数。','三个数中间是2。'),Q('所有数都加5，方差？',['加5','乘25','不变'],2,'每个数到新均值的距离不变。','整体平移不改变离散程度。'),Q('10人均分80，20人均分90，合并均分？',['85','260/3','90'],1,'把总分加起来再除总人数。','(10×80+20×90)/30=260/3≈86.67。')],'statistics','修改样本中的一个数，观察平均数、中位数和标准差。尝试加入一个特别大的数。');
add('b2',9,'9.3','统计案例：公司员工的肥胖情况调查分析','把调查结论一步步问清楚','一份调查出现了不同组的比例差异，先别急着找原因：抽了谁、怎么分组、样本大小是否一样，都需要看。','抽样、频率、均值与图表。',[
['明确问题与指标','先说调查对象、时间、样本来源和分类标准。教材以公司员工身体指标为案例，课程重点是统计过程：取样、整理、描述、比较，而不是凭一组数据判断某个人。',''],
['人数与比例要同时看','两组人数不同时，直接比较某类人数可能误导。先算各组该类别人数/该组总人数，再结合组容量与抽样方式理解差异。',r`\text{组内比例}=\frac{\text{该类人数}}{\text{该组总人数}}`],
['用图表检查分布差异','可把样本按性别、年龄等研究变量分组，比较直方图、均值、中位数和波动。分组标准与样本量要说明清楚，避免只挑支持猜想的一个数字。',''],
['从描述到解释要留一步','样本中两变量有关联，不等于已证明一个导致另一个；年龄、工作性质等因素可能同时影响两者。结论要对应调查设计，随后可设计新的观察或实验。','']
],[['甲组20人中6人符合预设类别，乙组40人中8人符合',['甲组比例6/20=30%。','乙组比例8/40=20%。','乙组人数更多，但组内比例更低。这个比较还不能单独说明原因。']],['怎样让调查报告便于复查？',['先写调查对象、抽样办法、有效样本量与分类口径。','给出数据表和能读清单位、频率的图。','最后分别写样本发现、总体估计和仍需验证的问题。']]],[Q('比较不同样本量两组的类别占比，主要先看？',['组内比例','只看类别人数','只看最大值'],0,'分母必须是各自组总人数。','比例能消除组容量不同带来的直接影响。'),Q('A组4/10，B组6/30，哪个比例高？',['A组','B组','相同'],0,'分别计算40%与20%。','A组40%，B组20%。'),Q('样本里两件事相关，是否已证明因果？',['已证明','没有，还需设计与其他证据','概率为1'],1,'还可能存在第三个影响因素。','相关关系不能直接替代因果判断。'),Q('报告只给“结果显著”四个字够吗？',['够','不够，要说明样本、方法和数据','不需要图表'],1,'别人需要能检查你怎样得到结论。','完整报告要让过程和证据清楚可查。')],'case','调整两组的总人数与类别人数，比较“人数更多”和“比例更高”能否同时成立。');
add('b2',10,'10.1','随机事件与概率','先列出可能，再看事件选中了谁','掷一枚骰子，“点数为偶数”不是一个新结果，而是从六个可能结果里选出2、4、6。','集合交并补；分数。',[
['样本点与样本空间','一次试验的每个基本结果叫样本点，所有可能结果构成样本空间Ω。事件是样本空间的子集；Ω是必然事件，∅是不可能事件。先确定一次试验到底做几步。',''],
['事件关系沿用集合语言','交事件AB或A∩B表示同时发生，并事件A∪B表示至少一个发生。互斥事件不能同时发生；对立事件不仅互斥，还覆盖全部可能。',''],
['古典概型要满足等可能','样本空间有限且各样本点等可能时，P(A)=A的样本点数/全部样本点数。若结果不等可能，不能只数有几类。',r`P(A)=\frac{|A|}{|\Omega|}`],
['概率的基本性质','概率在0到1之间，P(Ω)=1，P(∅)=0。互斥时并事件概率可相加；一般情形还要减掉同时发生的部分。',r`P(A\cup B)=P(A)+P(B)-P(A\cap B)`],
['对立事件有时更省力','“至少一次成功”的对立面是“一次也没成功”。若正面要分很多种，先求反面再用1减去，常更简单。',r`P(\overline A)=1-P(A)`]
],[['公平骰子出现偶数的概率',['Ω={1,2,3,4,5,6}，六个结果等可能。','A={2,4,6}，有3个样本点。','P(A)=3/6=1/2。']],['抽1到10中的一个整数，求偶数或大于7的概率',['偶数5个，大于7的数3个。','交集为8、10，共2个。','并集个数5+3−2=6，所以概率6/10=0.6。']]],[Q('公平骰子点数大于4的概率？',['1/6','1/3','1/2'],1,'有5、6两个符合的结果。','2/6=1/3。'),Q('“互斥”一定意味着“对立”吗？',['一定','不一定，还可能有两者都不发生','没有任何关系'],1,'比如点数1和点数2之外还有别的结果。','对立还要求并集等于整个样本空间。'),Q('P(A)=0.3，则对立事件概率？',['0.3','0.7','1.3'],1,'两者概率和为1。','1−0.3=0.7。'),Q('用古典概型数结果前，要确认？',['结果有限且等可能','名称好听','试验只能做一次'],0,'不是所有类别概率都相同。','有限、等可能是按个数相除的前提。')],'probability','选择骰子事件，查看交、并、补各包含哪些样本点，再核对概率。');
add('b2',10,'10.2','事件的相互独立性','能不能互相影响，和能不能同时发生不同','先抛一枚硬币再抛另一枚，第一枚结果通常不改变第二枚的机会；但“不影响”不是“不能一起出现”。','事件概率与交事件。',[
['独立的数学条件','A、B相互独立表示同时发生的概率恰好是两概率的乘积。直觉说“不影响”时，最后仍要用试验设计或这个等式检验。',r`P(A\cap B)=P(A)P(B)`],
['互斥与独立别混淆','互斥要求P(AB)=0；若A、B概率都大于0，独立时乘积>0，所以它们不能互斥。例如同一次骰子出现1与出现2互斥，但不独立。',''],
['独立时可以求连续成功','若各次试验相互独立，全部成功的概率为各次成功概率的乘积。有放回抽样常较容易保持相同条件，不放回时，在已知前次结果的条件下，后次概率一般会改变；各次位置的边缘概率仍可能相同。',''],
['补事件仍保持独立关系','若A、B独立，则A与B的补、A的补与B、两个补事件也独立。求“至少一个发生”可先算两个都不发生。',r`P(\overline A\cap\overline B)=[1-P(A)][1-P(B)]`]
],[['两枚公平硬币都正面的概率',['两次结果相互独立，每次正面概率1/2。','同时发生概率1/2×1/2=1/4。','可列HH、HT、TH、TT四个等可能结果核对。']],['独立设备成功率0.8与0.9，至少一个成功',['先算都失败：(1−0.8)(1−0.9)=0.02。','至少一个成功是其对立事件。','概率1−0.02=0.98。']]],[Q('独立事件A、B，P(A)=0.4、P(B)=0.5，则P(AB)？',['0.9','0.2','0.1'],1,'相互独立时才能直接乘。','0.4×0.5=0.2。'),Q('正概率的两个互斥事件能独立吗？',['能','不能','总是独立'],1,'交概率是0，但乘积大于0。','两个条件无法同时满足。'),Q('袋中2红1白，不放回抽，已知第一次红，第二次红的条件概率？',['1/2','2/3','1'],0,'第一次红被取走后，剩1红1白。','条件范围内剩2球，其中1红，因此概率1/2；这不等于未告知第一次结果时的边缘概率2/3。'),Q('两次独立成功率都是0.5，至少一次成功概率？',['0.5','0.25','0.75'],2,'先算两次都失败。','1−0.5²=0.75。')],'independence','对比放回与不放回抽取。观察第一次结果会不会改变第二次的样本构成。');
add('b2',10,'10.3','频率与概率','一次会晃动，很多次显出轮廓','公平硬币并不保证每10次恰好5次正面。试验频率会波动，重复很多次时往往稳定在概率附近。','比值、平均、随机试验。',[
['概率是模型，频率是这次记录','概率描述给定随机机制下事件发生的可能性；频率是实际发生次数/试验次数。一次试验结束后，频率确定，但换一批试验又会变化。',r`f_n(A)=\frac{n_A}{n}`],
['稳定不等于每一步靠近','大量重复时频率常在概率附近波动，但不会保证随次数增加每一步都更接近。也不保证有限次里恰好等于理论概率。',''],
['用频率估计未知概率','当机制稳定且试验合理重复时，可用大量试验的频率估计概率。估计精度与样本量、偏差、独立性等有关；别因连续几次结果就认定机制改变。',''],
['随机模拟的步骤','先把随机数与结果建立对应，再生成足够多次、统计目标事件、算频率。模拟的结果还依赖建模是否正确，不是按一下随机按钮就自动代表现实。','']
],[['100次抛币出现正面57次',['这批试验正面频率57/100=0.57。','若模型是公平独立抛币，理论概率仍为0.5。','0.57与0.5的差可以由随机波动造成。']],['连续3次正面后，下次反面会更容易吗？',['在公平独立模型下，过去不改变下一次结果概率。','下次反面仍为1/2。','“该补回来”是把长期规律误用成短期补偿。']]],[Q('200次试验成功90次，频率？',['0.45','0.5','90'],0,'次数除以总次数。','90/200=0.45。'),Q('试验增多，频率是否保证每一步更靠近概率？',['保证','不保证，仍会波动','概率会自动等于频率'],1,'稳定性不是单调性。','长期趋势不能改写成每一步都靠近。'),Q('公平独立硬币连续5次正面，下次正面概率？',['0','1/2','1'],1,'独立意味着前面结果不改变这次。','仍是1/2。'),Q('模拟现实问题前首先要？',['定义随机机制和对应规则','先生成漂亮图','把次数写得越大越好'],0,'模拟必须有清楚的模型。','先明确随机数如何对应真实结果。')],'frequency','先抛10次，再增加到100、1000次，比较频率曲线是否每一步都更靠近0.5。');
add('e1',11,'1.1','空间向量及其运算','把平面箭头带到三维空间','一架无人机向东、向北、再向上飞。计算总位移的方法仍然是箭头相接，只是多了一个方向。','平面向量运算；立体图形。',[
['大小与方向的定义继续成立','空间向量仍由大小和方向描述，平移后不变。相等、相反、共线、零向量等概念与平面一致，但箭头不必都在同一平面内。',''],
['加减和数乘照样算','三角形、平行四边形法则依旧适用；多次位移首尾相接形成总位移。数乘改变长度，负数再改变方向，交换、结合、分配律仍成立。',r`\overrightarrow{AB}+\overrightarrow{BC}=\overrightarrow{AC}`],
['共线与共面要区分','a、b共线可写b=λa（a≠0）。若a、b不共线，c与它们共面当且仅当c=xa+yb；它们张成的平面不会自动覆盖三维空间。',''],
['空间数量积','夹角仍取0到π。a·b=|a||b|cosθ，结果为数；垂直时数量积0，模平方等于自身数量积。沿某方向的投影长度可由数量积求出。',r`\operatorname{proj}_{\vec b}\vec a=\frac{\vec a\cdot\vec b}{|\vec b|^2}\vec b\quad(\vec b\ne0)`]
],[['东3、北4、再上12，总位移多长？',['水平位移长度√(3²+4²)=5。','再与竖直12构成直角三角形。','总位移√(5²+12²)=13；总路程是19，不能混用。']],['c=2a−b能说明什么？',['c是a与b的线性组合。','若a、b不共线，它们确定一个方向平面。','c与这两个方向共面，但不一定与其中某一个平行。']]],[Q('空间数量积的结果是？',['一个数','一个向量','一个平面'],0,'与平面数量积定义一致。','模的乘积乘夹角余弦，结果是实数。'),Q('非零向量a、b垂直，则a·b？',['1','0','−1'],1,'cos90°=0。','数量积为0。'),Q('a,b不共线，c=3a+2b说明？',['三向量共面','三向量一定共线','c必为零'],0,'只由两个独立方向合成。','c位于a,b张成的平面方向内。'),Q('连续位移的和应从哪指到哪？',['最后终点到最初起点','最初起点到最后终点','任意两点'],1,'向量加法仍按首尾相接。','和向量连接整体的起点和终点。')],'vectors3d','改变三维箭头的分量，观察总位移；把竖直分量设0，看它如何退回平面问题。');
add('e1',11,'1.2','空间向量基本定理','三根不共面的箭头，给空间做坐标架','两根箭头只能铺开一个平面。再加一根跳出平面的箭头，才有机会到达整个空间。','线性组合、共面与共线。',[
['空间基底需要三个不共面向量','如果e₁、e₂、e₃不共面，任意空间向量都能唯一写成xe₁+ye₂+ze₃。是否垂直、是否单位长度并非一般基底的必要条件。',r`\vec a=x\vec e_1+y\vec e_2+z\vec e_3`],
['唯一性为什么重要','同一个向量只能有一套分量，才能用分量来比较和计算。若三根基底共面，某些空间方向达不到，且表达可能不唯一。',''],
['选基底，尽量少绕路','在长方体中可选同一顶点发出的三条棱向量。它们天然不共面，许多棱、面对角线和体对角线都能直接拆成这三根。',''],
['位置关系转为系数关系','共线看是否互为倍数；共面看能否由同一组两个不共线方向合成；中点、三等分点、重心可按位置比例作加权组合；只有中点才是两端点的简单平均。','']
],[['以长方体三条棱向量a,b,c表示体对角线',['从顶点沿第一条棱走a，再沿平行第二条棱走b。','再沿竖棱方向走c，达到对顶点。','体对角线向量就是a+b+c。']],['a+b+c与a+b+c的两倍是什么关系？',['后一向量为2a+2b+2c。','它等于前一向量的2倍。','因此共线且同向，模为前者2倍。']]],[Q('空间基底的三个向量必须？',['不共面','都在同一平面','都长1'],0,'要覆盖三维空间。','不共面是空间基底的关键。'),Q('空间向量在给定基底下的表示？',['不唯一','唯一','总有四个系数'],1,'这是基本定理的内容。','每个向量对应唯一的三个系数。'),Q('一般基底一定互相垂直吗？',['一定','不一定','不能垂直'],1,'一般基底只要求不共面。','正交单位基底是特别方便的一类。'),Q('长方体体对角线可表示为同顶点三条棱向量的？',['和','模的和','积'],0,'按一条折线路径走到对顶点。','位移是向量和，长度不能直接相加。')],'vectors3d','沿三个基底方向合成一个向量，比较去掉一个独立方向后能否到达原来的点。');
add('e1',11,'1.3','空间向量及其运算的坐标表示','多一列z，计算方法并不陌生','地图再加一层楼高，坐标从两个数变成三个数。加减逐列算，长度和数量积也各多一项。','平面坐标向量、平方根。',[
['空间直角坐标','取两两垂直的单位基向量i,j,k。a=(x,y,z)表示xi+yj+zk。注意坐标轴和三个坐标平面各代表什么；z=0才在xOy平面上。',''],
['位移和运算逐项计算','AB=(xB−xA,yB−yA,zB−zA)。向量加减逐项进行，数乘乘到三个分量上。坐标是对当前坐标系的描述，不是向量的绝对名称。',r`\lambda(x,y,z)=(\lambda x,\lambda y,\lambda z)`],
['长度与两点距离','空间勾股定理把三个分量平方相加。求两点距离先求位移，再求模，别把坐标之和直接当距离。',r`|\vec a|=\sqrt{x^2+y^2+z^2}`],
['数量积与夹角','a·b=x₁x₂+y₁y₂+z₁z₂。求夹角时a,b均应非零。垂直查数量积0；共线查所有分量是否能对应同一个比例，遇0分量不要随意作商。',r`\cos\theta=\frac{x_1x_2+y_1y_2+z_1z_2}{|\vec a||\vec b|}`],
['用坐标检验几何关系','中点逐列平均；平行可尝试找一个λ满足三个方程；若某个分量对不上，就不是同一方向。把坐标结论翻回点、线、面的位置。','']
],[['A(1,0,2)，B(4,4,2)，求距离',['AB向量=(3,4,0)。','模=√(9+16+0)=5。','两点同高，结果与水平距离一致。']],['a=(1,2,2)，b=(2,−1,0)，判断垂直',['数量积1×2+2×(−1)+2×0=0。','两向量都不是零向量。','因此夹角90°，它们互相垂直。']]],[Q('(1,2,3)+(2,0,−1)是？',['(3,2,2)','(2,0,−3)','(1,2,4)'],0,'三个分量分别相加。','结果(3,2,2)。'),Q('(2,3,6)的模？',['11','7','49'],1,'平方和4+9+36=49。','模为√49=7。'),Q('点(x,y,z)在xOy平面需满足？',['x=0','y=0','z=0'],2,'xOy平面的高度为0。','z=0，x和y可以变化。'),Q('(1,0,0)与(0,2,0)的夹角？',['0°','90°','180°'],1,'它们的数量积为0。','两个非零向量垂直。')],'vectors3d','逐列修改坐标，核对模与数量积。让第三分量为0，比较二维与三维结果。');
add('e1',11,'1.4','空间向量的应用','把空间角和距离变成可算的投影','面对复杂立体图，先找直线方向和面的法向量。朝着法向方向量出的长度，就是到平面的垂直距离。','空间数量积；线面位置关系。',[
['直线方向，平面法向量','直线上任一非零平行向量叫方向向量。与平面内两个相交方向都垂直的非零向量叫法向量。求法向量可设n=(x,y,z)，列n·u=0、n·v=0，再选一个非零解。',''],
['位置关系，查方向与法向','两线平行看方向共线，垂直看数量积0。线与面垂直看方向与法向平行；线面平行时方向与法向垂直，还要排除线在面内。两面平行看法向共线，并区分重合。',''],
['线线角与线面角','两直线所成角取[0°,90°]，包括平行时的0°，余弦使用绝对值；线面角θ的正弦等于方向与法向数量积绝对值除以模的乘积。因为法向与面垂直，角互为余角。',r`\sin\theta=\frac{|\vec u\cdot\vec n|}{|\vec u||\vec n|}`],
['面面角要认清锐钝','两法向量可求两平面的锐角或直角：cosθ=|n₁·n₂|/(|n₁||n₂|)。若题目指定某个二面角，可能为钝角，必须结合半平面位置选择θ或π−θ。',''],
['点到面的距离','取面内一点A，待求点P，把AP投到法向方向。若平面写成Ax+By+Cz+D=0且A²+B²+C²>0，也能直接代公式；分母是法向量的模。',r`d=\frac{|Ax_0+By_0+Cz_0+D|}{\sqrt{A^2+B^2+C^2}}`],
['更多距离，也在找投影','点到直线的距离可用勾股：AP模平方减去沿线投影长度平方，再开根。平行线面、平行面面的距离可转成点到面；异面线可找同时垂直两方向的公共垂向，再求两线上点的位移在该方向的投影。','']
],[['点P(1,2,3)到平面z=0多远？',['平面法向量n=(0,0,1)。','取A=(0,0,0)，AP·n=3，|n|=1。','距离|3|/1=3，正是高度。']],['方向u=(1,0,1)与水平面夹角？',['水平面法向量n=(0,0,1)。','sinθ=|1|/(√2×1)=1/√2。','线面角在[0,90°]内，所以θ=45°。']]],[Q('平面的法向量应当？',['在平面内','垂直平面','一定长1'],1,'法向描述面的垂直方向。','任意非零垂直方向都可作法向量。'),Q('线面角公式使用方向与法向的数量积求？',['正弦','必须直接求正切','面积'],0,'方向和法向夹角与线面角互余。','绝对数量积除模乘积对应sinθ。'),Q('P(0,0,−4)到z=0的距离？',['−4','4','0'],1,'距离非负。','|−4|=4。'),Q('由法向量算出两面的锐角30°，指定二面角还可能是？',['150°','210°','只可能30°'],0,'需结合半平面方向判断补角。','相邻的二面角可能互补，钝角为180°−30°=150°。')],'spaceangle','改变直线方向与平面法向量，分别读取线面角和垂距，区分角度与长度。');
add('e1',12,'2.1','直线的倾斜角与斜率','斜率是每向右1，向上多少','爬坡时，水平前进2米上升1米，坡度可用1/2描述。竖直的路没有“每向右1”的空间，斜率也就不能定义。','正切、两点坐标。',[
['倾斜角的约定','直线向上的方向与x轴正向所成角叫倾斜角，取[0,π)。水平线角为0，竖直线为π/2，向右下降的线倾斜角在π/2与π之间。',''],
['斜率的两种算法','非竖直线斜率k=tanα。过两点时k=(y₂−y₁)/(x₂−x₁)，要求x₂≠x₁。分母0时不是斜率0，而是斜率不存在。',r`k=\frac{y_2-y_1}{x_2-x_1}`],
['符号与变化方向','k>0向右上升，k<0向右下降，k=0水平。|k|大表示与水平的坡度更陡，但不能用k的普通大小给所有倾斜角直接排序。',''],
['平行与垂直','两条不重合且斜率存在的直线平行当且仅当斜率相等；两条斜率存在的直线垂直当且仅当k₁k₂=−1。竖直与水平的垂直情形要单独处理。',r`k_1k_2=-1\quad\text{（两斜率均存在）}`]
],[['过(1,2)、(3,6)的斜率',['纵向变化6−2=4。','横向变化3−1=2。','k=4/2=2，每向右1向上2。']],['与斜率2的直线垂直的线斜率？',['设新斜率为k。','利用2k=−1。','k=−1/2；不是只把2变成−2。']]],[Q('过(0,1)、(2,5)的斜率？',['2','1/2','4'],0,'纵向变化4，横向变化2。','4/2=2。'),Q('竖直线斜率是？',['0','不存在','1'],1,'横向变化为0，不能作分母。','斜率不存在。'),Q('斜率−3的非竖直线向右怎样走？',['上升','下降','水平'],1,'斜率为负。','向右走时y减小。'),Q('斜率3与斜率−1/3的线？',['平行','垂直','一定重合'],1,'乘积是否−1？','3×(−1/3)=−1，互相垂直。')],'slope','拖动两点，观察横纵变化与斜率；让两点横坐标相同，查看为什么斜率不存在。');
add('e1',12,'2.2','直线的方程','知道经过哪里、朝哪走，就能写直线','“过点(1,2)，斜率3”意味着从这个点出发，横向变多少，纵向就变三倍。','斜率；一次方程。',[
['点斜式','过(x₀,y₀)且斜率k的直线是y−y₀=k(x−x₀)。先写结构，再代数。它不包含竖直线，竖直线应写x=x₀。',r`y-y_0=k(x-x_0)`],
['斜截式','斜率k与纵截距b给出y=kx+b。截距是交点的坐标值，可以为负，不是到原点的非负距离。',r`y=kx+b`],
['两点式','过两个不同点可用两点信息写方程；常见分式两点式要求两个分母都非零。若横坐标相同写竖直线，纵坐标相同写水平线。',r`\frac{y-y_1}{y_2-y_1}=\frac{x-x_1}{x_2-x_1}`],
['截距式','在x、y轴截距分别为a、b且二者非零时，x/a+y/b=1。过原点时不能用这个分式直接写，截距为0的分母无意义。',r`\frac xa+\frac yb=1`],
['一般式把竖直线也包含进来','Ax+By+C=0，A、B不能同时为0。B≠0可转斜截式，斜率−A/B；B=0时是竖直线。一般式系数同乘非零数，不改变直线。',r`Ax+By+C=0,\quad A^2+B^2\ne0`]
],[['过(1,2)，斜率3，写方程',['点斜式y−2=3(x−1)。','展开y−2=3x−3。','得到y=3x−1，代(1,2)能核对。']],['过(2,0)与(0,3)，写方程',['两轴截距a=2、b=3。','截距式x/2+y/3=1。','化为一般式3x+2y−6=0。']]],[Q('过(1,2)，斜率3的点斜式？',['y−2=3(x−1)','y+2=3(x+1)','y=3x+2'],0,'先放原点坐标到减号后。','代入(1,2)两边都为0。'),Q('x=4是一条怎样的线？',['水平','竖直','不是直线'],1,'每个点横坐标固定。','竖直线，斜率不存在。'),Q('2x+y−3=0的斜率？',['2','−2','3'],1,'改写成y=kx+b。','y=−2x+3，k=−2。'),Q('一般式A,B能否同时为0？',['能，总是直线','不能','只能A=B=1'],1,'否则不再描述一条直线。','A²+B²必须非0。')],'lines','调整斜率和截距，对照一般式与斜截式；再切到竖直线的特殊情况。');
add('e1',12,'2.3','直线的交点坐标与距离公式','联立找交点，投影找最短路','两条直线的交点同时满足两个方程；点到线的最短距离，必须沿垂直方向量。','联立一次方程；平方根；一般式。',[
['交点就是两个条件同时满足','联立方程若唯一解，则两线相交；无解则平行；无穷多解则重合。不要把没有交点和有无穷多交点混成“算不出来”。',''],
['两点距离与中点','横纵位移构成直角三角形，距离为平方和开根；中点坐标各取平均。这些公式也可用于求圆心、对称点与线段长度。',r`AB=\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}`],
['点到直线的距离','一般式Ax+By+C=0，代入点坐标，取绝对值，再除以√(A²+B²)。不取绝对值会误把距离算成负数。',r`d=\frac{|Ax_0+By_0+C|}{\sqrt{A^2+B^2}}`],
['两条平行直线的距离','先把两方程写成相同A、B，再取常数项之差的绝对值除以法向长度。系数未统一时不能直接减C。也可取一条线上一点，转成点到另一条线。',r`d=\frac{|C_1-C_2|}{\sqrt{A^2+B^2}}`]
],[['求y=x+1与y=−x+3交点',['两个y相等：x+1=−x+3。','2x=2，x=1。','代回y=2，交点(1,2)。']],['点(0,0)到3x+4y−10=0的距离',['代入绝对值为|−10|=10。','分母√(3²+4²)=5。','d=10/5=2。']]],[Q('y=x与y=−x交点？',['(0,0)','(1,1)','没有交点'],0,'联立x=−x。','x=0，y=0。'),Q('两点(0,0)、(6,8)距离？',['14','10','100'],1,'平方和是36+64。','√100=10。'),Q('点到直线公式分子为什么取绝对值？',['距离非负','为了增大系数','每次都可以不取'],0,'同一点在不同侧，代入值可能异号。','距离应始终非负。'),Q('求平行线距离前，应先？',['统一x,y项系数','直接减任意两个常数','只看图像'],0,'同一条线的方程还可成倍改写。','A,B一致后，C之差才有可比性。')],'intersection','移动两条线，查看联立方程的交点；选择平行情形，改为比较两线距离。');
add('e1',12,'2.4','圆的方程','离一个固定点一样远，就是圆','把绳子一端固定，另一端拉紧画一圈。固定点是圆心，绳长是半径，坐标方程就是距离条件。','两点距离；配方。',[
['标准方程直接读圆心半径','圆心(a,b)，半径r>0，所有点到圆心距离r。坐标差平方相加等于r²。方程里是x−a而不是看到加号就照抄圆心符号。',r`(x-a)^2+(y-b)^2=r^2`],
['一般方程要配方','x²+y²+Dx+Ey+F=0可能表示圆；配方得圆心(−D/2,−E/2)，半径平方(D²+E²−4F)/4。只有半径平方>0才是一个真正的圆。',r`r^2=\frac{D^2+E^2-4F}4`],
['点在圆内、上、外','把点代入左边的距离平方，与r²比较：小于在内，等于在上，大于在外。不必每次都先开平方。',''],
['用条件确定圆','已知圆心和半径最直接；若给三个不共线点，可设一般式再代入解D,E,F。三点共线时不能确定经过它们的普通圆；设式前先看条件。','']
],[['读圆(x−2)²+(y+1)²=9',['圆心横坐标2，纵坐标−1。','半径平方9，因此半径3。','把圆心代入左边得0，可核对符号。']],['化简x²+y²−4x+2y−4=0',['x项配方(x−2)²−4。','y项配方(y+1)²−1。','移项得(x−2)²+(y+1)²=9，圆心(2,−1)，半径3。']]],[Q('(x+3)²+(y−2)²=16的圆心？',['(3,−2)','(−3,2)','(−3,−2)'],1,'括号里写的是坐标差。','x−(−3)、y−2，所以圆心(−3,2)。'),Q('x²+y²+1=0在实平面表示圆吗？',['表示单位圆','不表示，因为半径平方为负','表示半径1的圆'],1,'平方和不可能为−1。','不存在实点满足，不能称普通圆。'),Q('圆心到P的距离小于半径，P在？',['圆外','圆上','圆内'],2,'绳长还没拉到边界。','距离小于r在圆内。'),Q('三个不共线点能确定几个圆？',['唯一一个','无限多个','0个'],0,'它们的垂直平分线交于唯一圆心。','三个不共线点唯一确定一个圆。')],'circle','拖动圆心与半径，核对方程符号，再放入一个测试点判断内、上、外。');
add('e1',12,'2.5','直线与圆、圆与圆的位置关系','先量圆心到线的距离','直线从圆外移过来，先不相交，再擦到一点，最后穿过两点。圆心到线的距离决定这些变化。','点线距离；圆的标准方程。',[
['线与圆，比较d与r','圆心到直线距离d>r相离，d=r相切，d<r相交。也可联立得到一元二次方程，用判别式判断交点数。',r`d\mathrel{\gtrless}r\quad\Longleftrightarrow\quad\text{相离/相交}`],
['弦长与垂径','相交时，圆心到弦的垂线平分弦。半弦长√(r²−d²)，全弦长为其2倍。用勾股比联立求两个点再作差更快。',r`L=2\sqrt{r^2-d^2}`],
['过圆上一点的切线','切线垂直该点半径。圆心(a,b)、圆上点(x₀,y₀)时，可按数量积为0写出切线；特殊竖直切线也能覆盖。',r`(x_0-a)(x-a)+(y_0-b)(y-b)=r^2`],
['两个圆，比较圆心距与半径和差','设R≥r>0，圆心距d。d>R+r外离；等于和为外切；R−r<d<R+r相交；等于差且R>r为内切；d<R−r内含。同心同半径是重合圆，要另列。',''],
['两圆方程相减','两个圆的二次项相减抵消，可得到公共弦所在直线（有两个交点时）。还需与任一圆联立求实际交点，不能把这条直线的所有点都当成两圆交点。','']
],[['半径5的圆，圆心到直线距离3，弦长？',['取半弦与半径、高度组成直角三角形。','半弦√(25−9)=4。','全弦长8。']],['两圆半径3、2，圆心距5是什么位置？',['半径和3+2=5，半径差1。','圆心距恰等于半径和。','两圆外切，只有一个公共点。']]],[Q('d=r时，直线与圆？',['相切','相交两点','相离'],0,'恰好擦到一点。','圆心到线距离等于半径，是相切。'),Q('r=5,d=4的弦长？',['3','6','10'],1,'半弦√(25−16)=3。','全弦为6。'),Q('半径4、1，圆心距1，两圆？',['外离','内含','相交'],1,'比较d与半径差3。','1<3，小圆在大圆内部且不相切。'),Q('圆的切线与切点半径？',['平行','垂直','方向不确定'],1,'切点处半径是切线法向。','二者垂直。')],'circleline','平移直线穿过圆，观察0、1、2个交点切换；核对弦长与圆心距。');
add('e1',13,'3.1','椭圆','到两个定点的距离和不变','用两根图钉和一根线画出的曲线，保持的是到两图钉的距离之和，而不是到中心的距离。','两点距离；平方根；坐标轴。',[
['定义先看距离和','到两个定点F₁、F₂距离和为2a，且2a大于焦点间距2c，轨迹是椭圆。若等于焦距会退化，不能套成普通椭圆。',r`|PF_1|+|PF_2|=2a>2c`],
['标准方程与长轴','中心在原点，焦点在x轴时x²/a²+y²/b²=1，a>b>0，且c²=a²−b²。分母较大的那个变量对应长轴；若大分母在y下，焦点在y轴。',r`\frac{x^2}{a^2}+\frac{y^2}{b^2}=1,\quad c^2=a^2-b^2`],
['顶点、范围、对称','水平长轴椭圆范围|x|≤a、|y|≤b；关于两轴与原点对称。长轴端点(±a,0)，短轴端点(0,±b)，焦点(±c,0)。',''],
['离心率，量出扁不扁','非圆椭圆e=c/a，0<e<1。越接近0越接近圆，越接近1越扁。a、b、c不能独立乱选；a²=b²+c²一直要满足。',r`e=\frac ca`],
['直线与椭圆联立','把直线代入椭圆，通常得到二次方程，用根或判别式找交点、弦长；求中点也可用根的和。运算前先确认坐标范围，最后把点代回原式检验。','']
],[['椭圆x²/25+y²/9=1，找焦点与离心率',['a=5，b=3，焦点在x轴。','c=√(25−9)=4，焦点(±4,0)。','e=4/5，长轴长10，短轴长6。']],['长半轴5，焦距6，求方程（焦点在x轴）',['焦距2c=6，所以c=3。','b²=a²−c²=25−9=16。','方程x²/25+y²/16=1。']]],[Q('椭圆的定义固定的是？',['到两焦点距离和','到两焦点距离差','到一条线距离'],0,'线绳的总长固定。','两段距离的和保持不变。'),Q('x²/16+y²/25=1的焦点在哪条轴？',['x轴','y轴','无法确定'],1,'大分母对应长轴方向。','25在y²下，焦点在y轴。'),Q('a=5,b=4时c？',['3','9','√41'],0,'c²=a²−b²。','√(25−16)=3。'),Q('非圆椭圆的离心率范围？',['e>1','0<e<1','e=1'],1,'焦点离中心小于长半轴。','c<a，所以0<e<1。')],'ellipse','改变长短半轴，观察焦点如何变化；检查任一点到两焦点的距离和。');
add('e1',13,'3.2','双曲线','这次固定的是两段距离之差','椭圆把两段距离加起来；双曲线比较两段距离相差多少。结果会分成左右或上下两支。','椭圆参数、坐标、渐近趋势。',[
['定义有绝对值与范围','到两定点距离差的绝对值等于2a，且0<2a<2c，轨迹为双曲线。绝对值保证两支都被包含；若只写一个有符号差，一般只得到一支。',r`\bigl||PF_1|-|PF_2|\bigr|=2a<2c`],
['标准方程看正项','x²/a²−y²/b²=1时开口和焦点沿x轴；y²/a²−x²/b²=1时沿y轴。a,b都为正，但大小无需a>b。参数满足c²=a²+b²。',r`\frac{x^2}{a^2}-\frac{y^2}{b^2}=1,\quad c^2=a^2+b^2`],
['顶点、范围与渐近线','水平双曲线顶点(±a,0)，范围|x|≥a。渐近线y=±(b/a)x，给出远处靠近的方向。曲线不会因为图像很近就与渐近线重合。',''],
['离心率大于1','e=c/a>1，因为c²=a²+b²>a²。a=b时渐近线互相垂直，称等轴双曲线，e=√2。',''],
['直线联立时留意降次','代入后若二次项系数为0，方程可能降成一次，只有一个交点也不一定表示相切。例如与渐近线平行的直线常出现这种情况；先判断方程次数，再谈判别式。','']
],[['x²/9−y²/16=1，求焦点与渐近线',['a=3，b=4，所以c=5。','焦点(±5,0)，e=5/3。','渐近线y=±4x/3。']],['为什么双曲线不能用c²=a²−b²？',['双曲线标准式中间是减号。','从定义推得的参数关系是c²=a²+b²。','若套错椭圆公式，会把焦点放到不合理的位置。']]],[Q('双曲线x²/4−y²/9=1焦点方向？',['x轴','y轴','45°方向'],0,'看哪个平方项是正项。','正项是x²，焦点沿x轴。'),Q('双曲线a=3,b=4，则c？',['1','5','√7'],1,'c²=a²+b²。','√25=5。'),Q('水平双曲线渐近线斜率？',['±b/a','±a/b一定不分方向','总为±1'],0,'方程的二次主项相抵。','y=±(b/a)x。'),Q('联立只有一个交点就一定相切吗？',['一定','不一定，可能降成一次方程','从不相切'],1,'检查二次项是否还存在。','圆锥曲线联立时降次可能导致单交点但并非相切。')],'hyperbola','改变a,b，对照双曲线、焦点和渐近线，观察远处曲线靠近什么方向。');
add('e1',13,'3.3','抛物线','到一个点和一条线一样远','取一个固定点和一条不经过它的直线，寻找离两者同样远的点。这条轨迹就是抛物线。','点线距离、平方、二次函数。',[
['焦点与准线','定点叫焦点，定直线叫准线。点到线的距离取垂直距离。焦点不能落在准线上，否则轨迹退化，不能作为普通抛物线。',''],
['标准方程中的2p','右开口抛物线y²=2px，p>0，焦点(p/2,0)，准线x=−p/2，顶点原点。p是焦点到准线的距离，不是焦点到顶点的距离。',r`y^2=2px\quad(p>0)`],
['四种开口，盯住一次项','y²=2px向右，y²=−2px向左；x²=2py向上，x²=−2py向下。对称轴沿未平方的那个变量，顶点为原点。',''],
['焦半径可以化简','右开口时点P横坐标x≥0，到准线距离x+p/2，所以到焦点距离也等于x+p/2。用定义可以减少开平方运算。',r`|PF|=x+\frac p2`],
['用定义和联立处理应用','求轨迹先写距离相等再化简；与直线相交可联立。平行对称轴的直线可能只交一点，却不是切线，所以仍需查看是否降次和图形位置。','']
],[['y²=8x的焦点和准线？',['对照2p=8，所以p=4。','焦点(p/2,0)=(2,0)。','准线x=−2，别误写成±4。']],['点P在y²=8x上，x=3，到焦点多远？',['上题p=4。','利用抛物线定义，距离等于到准线x=−2的垂距。','3−(−2)=5，无需先求P的纵坐标。']]],[Q('y²=12x的焦点？',['(6,0)','(3,0)','(0,3)'],1,'2p=12，先算p再除2。','p=6，焦点(3,0)。'),Q('x²=−4y开口朝哪？',['上','下','右'],1,'一次项为负y。','对称轴竖直，开口向下。'),Q('抛物线上点到焦点的距离等于？',['到准线的垂直距离','到准线任意点的距离','总是p'],0,'这就是定义。','准线距离必须取最短的垂直距离。'),Q('y²=8x上x=1的点到焦点距离？',['1','2','3'],2,'p/2=2，焦半径x+p/2。','1+2=3。')],'parabola','移动曲线上的点，比较到焦点与到准线的两段距离；切换开口方向。');
add('e2',14,'4.1','数列的概念','一串有顺序的数，也是一种函数','电影院第1排、第2排的座位数按顺序记录，就得到数列。相同数字出现在不同位置，不会像集合那样被去掉。','函数、正整数、代入。',[
['顺序决定第几项','数列是按一定次序排列的一列数，记作a₁,a₂,…。第n项aₙ中的n是位置，是正整数，不是这一项的值。可有有限项，也可有无限项。',''],
['数列是定义在正整数上的函数','自变量n只取1,2,…或前若干正整数，函数值是aₙ。画图应是离散点，不能无条件把相邻项连成一条连续曲线。',r`n\mapsto a_n`],
['通项与递推，两种描述','通项公式直接从n算aₙ；递推公式从前面项推后面项，还必须给起始值。例如a₁=1、aₙ₊₁=aₙ+2得到正奇数列。',''],
['前n项和与第n项','Sₙ=a₁+…+aₙ。a₁=S₁；n≥2时aₙ=Sₙ−Sₙ₋₁。不能直接把n=1代进一个没有S₀定义的式子。',r`a_n=S_n-S_{n-1}\quad(n\ge2)`],
['观察规律，不等于唯一规律','有限几个数字可以符合很多不同公式。题目给定定义或规律后才能推得确定结论，不能仅凭“看起来像”就宣布通项唯一。','']
],[['aₙ=2n−1，求第5项和前5项和',['代n=5，a₅=9。','前5项为1、3、5、7、9。','S₅=25；第5项和前5项和不是同一件事。']],['已知Sₙ=n²，求aₙ',['n=1时a₁=S₁=1。','n≥2时aₙ=n²−(n−1)²=2n−1。','这个式子在n=1也得1，因此可以统一为aₙ=2n−1。']]],[Q('a₇中的7表示？',['第7项的位置','函数值一定为7','前7项和'],0,'下标标记序号。','第7项的值要根据具体数列计算。'),Q('n≥2时aₙ等于？',['Sₙ+Sₙ₋₁','Sₙ−Sₙ₋₁','Sₙ/Sₙ₋₁'],1,'相邻两个前缀和相减。','前n−1项抵消，只剩第n项。'),Q('数列图像的横坐标通常取？',['所有实数','相应正整数','只有0'],1,'每项有离散的序号。','数列是以正整数为自变量的函数。'),Q('只给aₙ₊₁=aₙ+2，能唯一确定整个数列吗？',['能','不能，还需起始项','每项一定是2'],1,'第一项可以不同。','不同a₁会产生不同数列。')],'sequence','切换通项与递推规则，只把整数序号处画成点，比较第n项与前n项和。');
add('e2',14,'4.2','等差数列','每一步都加同一个数','台阶每级都比前一级高相同高度，这样的“固定增加量”正是等差数列。','数列通项、一次函数。',[
['公差：后一项减前一项','从第2项开始，每项与前项的差都相同，叫等差数列，差为d。d可正、负或0；d=0时是常数列。',r`a_{n+1}-a_n=d`],
['通项：第一项加上n−1次公差','从第1项到第n项只跨了n−1步，因此aₙ=a₁+(n−1)d。也可从第m项走n−m步，不必次次绕回第1项。',r`a_n=a_m+(n-m)d`],
['等差中项与对称项','a,b,c成等差当且仅当2b=a+c。若m+n=p+q，则aₘ+aₙ=aₚ+a_q；首尾配对能解释求和公式。',''],
['倒序相加得到和','同一串数正着、倒着各写一次，对应每对的和都是a₁+aₙ。共有n对，得到2Sₙ=n(a₁+aₙ)。',r`S_n=\frac{n(a_1+a_n)}2=na_1+\frac{n(n-1)}2d`],
['前n项和与项的正负','当d≠0，等差通项是n的一次表达式，和是n的二次表达式；d=0时通项为常数、Sₙ=na₁。若先正后负，求和常在最后一个正项附近最大；n只能是正整数，要查邻近整数并核对项的符号。','']
],[['a₁=3,d=2，求a₁₀和S₁₀',['a₁₀=3+9×2=21。','S₁₀=10(3+21)/2。','结果120。检查不是把公差加10次。']],['a₃=7，a₈=22，求公差',['从第3项到第8项跨5步。','a₈−a₃=5d=15。','d=3，第一项a₁=7−2×3=1。']]],[Q('a₁=2,d=3，第4项？',['11','14','8'],0,'从第1项到第4项走3步。','2+3×3=11。'),Q('5、b、13成等差，b？',['8','9','10'],1,'中间等于两端平均。','b=(5+13)/2=9。'),Q('1+2+…+100等于？',['5000','5050','10000'],1,'首尾配对101，共100项。','100×101/2=5050。'),Q('d<0时等差数列怎样变化？',['递减','递增','一定为负数'],0,'每一步减去同一个正量。','d<0表示项值逐步减小，但各项未必全负。')],'arithmetic','改变首项和公差，对照离散点与前n项和，核对n−1到底对应几步。');
add('e2',14,'4.3','等比数列','每一步都乘同一个非零数','纸张每折一次，层数变成2倍。固定的是比例，不是每次增加的层数。','指数、数列。',[
['公比与非零条件','从第2项起，每项与前项的比都相同，叫等比数列。按本书定义，各项非零，公比q也非零。q=1是非零常数列；q<0会正负交替。',r`\frac{a_{n+1}}{a_n}=q\ne0`],
['通项：跨几步就乘几次','aₙ=a₁qⁿ⁻¹；从第m项到第n项为aₙ=aₘqⁿ⁻ᵐ。若0<q<1且a₁>0，数列递减；q>1且a₁>0则递增，负首项需再判断方向。',r`a_n=a_1q^{n-1}`],
['等比中项与乘积性质','a,b,c为非零实数时，三项成等比等价于b²=ac。若a,c>0，中项b可正可负；“正的几何平均”才专指√ac。序号和相同的两项乘积也相同。',''],
['错位相减求和','Sₙ与qSₙ相减，中间项抵消。q≠1时Sₙ=a₁(1−qⁿ)/(1−q)；q=1时不能除以0，应直接用Sₙ=na₁。',r`S_n=\begin{cases}na_1,&q=1\\a_1\dfrac{1-q^n}{1-q},&q\ne1\end{cases}`],
['识别混合形式','看到每次乘固定倍数，先想等比；等差乘等比、或由和反推项，可能要错位相减、分组或裂项。每次引入公式先查它的定义条件。','']
],[['a₁=2,q=3，求第4项与前4项和',['a₄=2×3³=54。','S₄=2(1−3⁴)/(1−3)。','得到80；直接2+6+18+54也为80。']],['等比数列a₁=3,q=1，前10项和？',['每一项都等于3。','不能把q=1代入分母1−q的公式。','直接相加，S₁₀=10×3=30。']]],[Q('2、6、18的公比？',['3','4','12'],0,'后一项除以前一项。','6/2=18/6=3。'),Q('a₁=1,q=2，第5项？',['10','16','32'],1,'从第1项到第5项乘4次。','a₅=2⁴=16。'),Q('q=1时前n项和公式？',['a₁(1−qⁿ)/(1−q)照用','na₁','a₁+n'],1,'每一项都相同。','直接n次相加得到na₁。'),Q('等比中项b满足b²=9时，b可能？',['只有3','只有−3','3或−3'],2,'平方方程可有两个非零根。','若没有正值限制，b=±3。')],'geometric','比较q=2、q=1/2、q=−1的点列，观察增长、衰减与交替，并检查求和公式。');
add('e2',14,'4.4','★ 数学归纳法','像多米诺：第一块倒下，还要保证能传下去','检查前100个数仍不能保证所有正整数成立。归纳法把无限多情况压成“起点成立”和“每一步能传递”两件事。','正整数、代数恒等变形。',[
['第一步：核对起始位置','命题若从n=n₀开始，就先证明该起始值成立。不一定总从1开始，题目范围是什么，第一块就放在哪里。',''],
['第二步：假设第k项，推出第k+1项','假设任意k≥n₀时命题成立，利用这个假设推出k+1也成立。这是假设一个一般位置的命题，不是直接假设所有位置都成立。',''],
['两步必须都具备','只有起点，没有传递，链条断掉；只有传递，没起点，链条也未启动。两者结合才能覆盖所有n≥n₀的整数。',''],
['推k+1时，真的用上归纳假设','求和类常把Sₖ₊₁拆成Sₖ加新的一项，再代入假设。别把要证明的k+1结论先写成已成立，这会循环论证。',r`S_{k+1}=S_k+a_{k+1}`]
],[['证明1+2+…+n=n(n+1)/2',['n=1时左边1，右边1，成立。','假设到k成立；到k+1时，和=k(k+1)/2+(k+1)。','提取k+1得到(k+1)(k+2)/2，恰是下一项形式，故对全部正整数成立。']],['为什么只验证前10项不够？',['后面的第11项可能出现改变规律的项。','有限验证没有给出从任意k到k+1的逻辑。','需要一条能覆盖每一步的推导，才称归纳证明。']]],[Q('归纳法需要哪两步？',['起点成立与递推成立','验证前两项','直接假设结论'],0,'既要开始，又要能传下去。','两步共同覆盖所有后续整数。'),Q('归纳假设应是？',['任意k≥n₀时的命题成立','所有n都成立无需证明','k+1已成立'],0,'用第k项去推第k+1项。','假设任意一般位置k的情况，再推下一步。'),Q('题目范围n≥3，最初要验证？',['n=0','n=1','n=3'],2,'从命题覆盖的第一个整数开始。','起点应为3。'),Q('已验证前100项，就能证明所有正整数吗？',['能','不能','只要数字够大就能'],1,'有限检查仍遗漏无限多个位置。','还缺一般的递推论证。')],'induction','展开多米诺步骤，检查“起点”和“传递”少掉哪一个都会怎样。');
add('e2',15,'5.1','导数的概念及其意义','从一段路的平均速度，走向某一刻的速度','走完100米用了20秒，平均速度5米/秒；但起跑和冲刺时的速度可能完全不同。把时间段缩小，才能看清某一刻。','函数、割线斜率、代数化简。',[
['平均变化率是差的比','在x₀到x₀+h的一段上，平均变化率=[f(x₀+h)−f(x₀)]/h，h≠0。它可以是正、负或0，对应割线斜率。',r`\frac{\Delta y}{\Delta x}=\frac{f(x_0+h)-f(x_0)}h`],
['让间隔趋近0','若h从正、负两侧趋近0时，比值趋向同一个有限值，这个值叫f在x₀的导数。不是把h直接设0后算0/0，而是先化简、观察趋近。',r`f'(x_0)=\lim_{h\to0}\frac{f(x_0+h)-f(x_0)}h`],
['切线斜率与瞬时速度','几何上导数是切线斜率，物理上位移函数对时间的导数是瞬时速度。切线不是“与曲线只交一点”的线，它可能再次与曲线相交。',''],
['从一个导数值到导函数','把x₀换成一般位置x，可得到导函数f′(x)。先求导再代位置，可以得到各点的变化率；不能先把x代成常数再求导，否则丢掉变化。',''],
['不是每一点都有导数','例如|x|在0左右的斜率分别−1与1，不能趋向同一值，所以0处不可导。图像连续不自动保证可导；可导则连续。','']
],[['用定义求f(x)=x²在x₀处的导数',['差商=[(x₀+h)²−x₀²]/h。','展开并约去h，得到2x₀+h，前提h≠0。','h趋近0，导数2x₀；在x₀=3时为6。']],['求y=x²在(2,4)处切线',['导函数f′(x)=2x，斜率f′(2)=4。','切线过(2,4)，点斜式y−4=4(x−2)。','整理y=4x−4。']]],[Q('平均变化率的分母是什么？',['函数值本身','自变量的变化量','导数值'],1,'用输出变化除输入变化。','分母为Δx或h。'),Q('x²在x=2处的导数？',['2','4','8'],1,'导函数为2x。','代入2得到4。'),Q('求导定义中，可以直接把h=0代进原差商吗？',['可以','不可以，要观察h趋近0','永远等于0'],1,'原式分母h不能为0。','先化简或分析极限，不能直接作0/0。'),Q('|x|在0处左右斜率−1与1，因此？',['可导且导数0','不可导','导数1'],1,'两侧需要趋于同一个值。','左右不一致，不存在导数。')],'tangent','让割线的两个点慢慢靠近，比较割线斜率与固定位置的切线斜率。');
add('e2',15,'5.2','导数的运算','先认清结构，再选择求导规则','同是两个函数放在一起，相加、相乘、相除的求导方法不一样；尤其乘法不是把两个导数直接相乘。','导数意义；指数、对数、三角函数。',[
['常数与幂函数','常数变化率0；在可导的定义范围内，(x^α)′=αx^(α−1)。例如x³导数3x²，1/x导数−1/x²（x≠0），√x在x>0处导数1/(2√x)。',r`(C)'=0,\quad(x^\alpha)'=\alpha x^{\alpha-1}`],
['指数、对数与三角函数','记住e^x导数仍为自身，lnx导数1/x；a^x多乘lna，log_a x多除lna。三角函数求导时角以弧度计。',r`(e^x)'=e^x,\ (\ln x)'=\frac1x,\ (\sin x)'=\cos x,\ (\cos x)'=-\sin x`],
['和差与常数倍','和差的导数等于导数的和差，常数倍系数可以留在外面。先展开简单多项式，再逐项求导，通常最省力。',r`(af+bg)'=af'+bg'`],
['乘积规则','fg的导数=f′g+fg′。像“左边动、右边暂不动”加“右边动、左边暂不动”。不是f′g′。',r`(fg)'=f'g+fg'`],
['商的规则','分母非零处，分子导数乘分母，减分子乘分母导数，再除分母平方。要保留减号与定义域。',r`\left(\frac fg\right)'=\frac{f'g-fg'}{g^2}`],
['复合函数，外层导数还要乘内层导数','先看内外层。例如sin(2x+1)外层是sin，内层是2x+1；求导得2cos(2x+1)。内层系数不能漏。',r`[f(ax+b)]'=a f'(ax+b)`]
],[['求x³−2x+5的导数',['x³导数3x²。','−2x导数−2，常数5导数0。','合为3x²−2。']],['求x e^x的导数',['识别这是乘积，不是和。','导数=1×e^x+x×e^x。','整理为(1+x)e^x。']],['求lnx/x的导数',['定义域x>0。','分子按商法则为(1/x)×x−lnx×1=1−lnx。','除以x²，得(1−lnx)/x²。']]],[Q('(x⁴)′等于？',['4x³','x³','4x⁴'],0,'指数变系数，指数再减1。','4x^(4−1)=4x³。'),Q('(sin 3x)′等于？',['cos3x','3cos3x','−3sin3x'],1,'别漏掉内层3x的导数。','外层cos3x再乘3。'),Q('(fg)′的规则？',['f′g′','f′g+fg′','f′+g′'],1,'分别让一边变化。','乘积法则有两项。'),Q('(lnx)′的定义范围？',['x>0','所有实数','x≠0即可'],0,'原函数lnx只允许正输入。','导数1/x也要保留原定义域x>0。')],'derivative','切换函数，对比原图与导数图；先猜导数正负，再用计算结果核对。');
add('e2',15,'5.3','导数在研究函数中的应用','斜率的正负，画出上坡和下坡','不用逐个点试算，就能通过导数符号判断一段函数正在上升还是下降，还能找到可能的峰谷。','求导、解不等式、区间。',[
['导数符号与单调性','在区间内可导，若f′>0则递增，f′<0则递减。导数个别点等于0，不一定破坏严格递增，比如x³在0导数0仍递增。不要把充分条件写成“处处必须>0”。',''],
['先找分界，再分段判符号','求导、解f′=0，加入定义域断点和不可导点作分界，在各区间取样看符号。每个结论都要写在哪个区间成立。',''],
['极大极小看左右变化','导数从正到负，附近先升后降，为极大；从负到正为极小。只知f′(x₀)=0还不够，例如x³在0左右导数均非负，没有极值。',''],
['极值与最值不同','极值只比较附近，最大最小比较整个给定范围。连续函数在闭区间上求最值，要比较内部候选极值点、不可导点以及两个端点。',''],
['用导数解决实际最优问题','先建函数与实际定义域，再求导找候选点，检查该点是否允许、是否真为最优，并用原单位解释。人数或件数只取整数时，还要查邻近整数。','']
],[['f(x)=x³−3x，找增减与极值',['f′=3x²−3=3(x−1)(x+1)，分界−1、1。','两端区间导数正，中间负，所以先增、再减、再增。','x=−1极大值2；x=1极小值−2。']],['长方形两边和为10，用导数求最大面积',['设一边x，另一边10−x，0<x<10。','面积S=10x−x²，S′=10−2x。','x<5时递增，x>5时递减；x=5面积最大25。']]],[Q('某区间f′(x)<0，函数在该区间？',['递增','递减','恒为0'],1,'切线斜率负意味着向右下走。','函数递减。'),Q('f′(x₀)=0一定有极值吗？',['一定','不一定，如x³在0','一定是最大值'],1,'还要看左右导数是否变号。','驻点不必是极值点。'),Q('导数从正变负，对应？',['极大','极小','无法发生'],0,'先升后降形成山峰。','该点为极大值点。'),Q('闭区间求最大值，能否只查内部导数为0的点？',['能','不能，还要比较端点等候选','端点不允许'],1,'最高点可能就在边界。','连续闭区间的端点也是最值候选。')],'derivativeapp','移动观察点，联动查看函数值与导数正负，找到“正→负”和“负→正”的位置。',['★ 文献阅读与数学写作：微积分的创立与发展。把“求切线”“求瞬时速度”怎样汇成统一方法写成一段自己的解释。']);
add('e3',16,'6.1','分类加法计数原理与分步乘法计数原理','是“选一条路”，还是“走完几步”','从家到学校可以坐公交或骑车，这是分类；选上衣再选裤子，这是分步。两种任务不能都用同一个运算。','加法、乘法、集合。',[
['分类完成一件事，用加法','每一类都能独立完成任务，各类不重复、合起来不遗漏，则总方法数相加。若类别有重叠，要先去重或重新分类。',r`N=m_1+m_2+\cdots+m_k`],
['分步完成一件事，用乘法','必须依次做完所有步骤才完成任务，若各步可选数按规则明确，总方法数为各步选择数之积。画树状图能看清每条完整路径。',r`N=m_1m_2\cdots m_k`],
['后一步可能依赖前一步','不能随便假定每一步都有同样多的选择。不重复选人时，选完一个就少一个；若不同前缀分支的选择数不同，可先分类后在每类里分步。',''],
['元素选不选，也是两步状态','n个元素组成的集合，每个元素只有“选入/不选入”两种决定，因此共有2ⁿ个子集，包含空集与全集。','']
],[['3件上衣、2条裤子，共多少搭配？',['一套搭配必须选上衣并选裤子，是分步。','每件上衣都可配2条裤子。','总数3×2=6套。']],['公交3条线路，地铁2条线路，任选一种直达',['每一条线路都能独立完成到达任务。','公交和地铁线路按题意不重复，是分类。','共有3+2=5种选择，而不是相乘。']]],[Q('完成任务可选A方法3种或B方法4种且不重复，总数？',['7','12','1'],0,'两类任一类都能完成。','分类相加3+4=7。'),Q('3种饮料与4种主食各选一种，套餐数？',['7','12','3'],1,'要做完两步。','3×4=12。'),Q('4个元素的集合有多少子集？',['8','16','4'],1,'每个元素选或不选。','2⁴=16。'),Q('分类计数时两类重叠，直接相加会？',['重复计算','总是正确','变成概率'],0,'重叠对象进入了两个类别。','要调整分类或用容斥去重。')],'counting','切换“二选一的路线”和“都要完成的步骤”，用树状图核对加法与乘法。');
add('e3',16,'6.2','排列与组合','选了谁，与谁排在前面，是两种问题','从5人里选2人当小组成员，不分先后；选组长和副组长，交换两人职位就变成另一种结果。','计数原理、阶乘。',[
['排列：选出后还分顺序','从n个不同元素中取m个按顺序排列，数目Aₙᵐ=n(n−1)…(n−m+1)。n个全排列为n!，并规定0!=1。',r`A_n^m=\frac{n!}{(n-m)!}`],
['组合：只看选中谁','从n个不同元素中取m个，不管顺序，数目Cₙᵐ=Aₙᵐ/m!。因为同一组m人会在排列里重复出现m!种顺序。',r`C_n^m=\frac{n!}{m!(n-m)!}`],
['两个组合数性质','选m个与选剩下n−m个一一对应，所以Cₙᵐ=Cₙⁿ⁻ᵐ。按某个人选或不选分类，可得相邻相加性质。',r`C_n^m+C_n^{m-1}=C_{n+1}^m`],
['带限制时先照顾特殊条件','相邻可把两人捆成一块，块内仍要排序；不相邻可先排其余人再插空；固定位置先安排受限元素。每一步说明究竟选谁、排谁。',''],
['分组要防止同组重复','把6人分成三对，先挑两人、再挑两人、最后两人，会把三组的出现次序重复算3!次。无标签组应除掉组间重复；若各组有指定任务，情况不同。',r`\frac{C_6^2C_4^2C_2^2}{3!}=15`]
],[['5人选2人任组长、副组长',['职位不同，顺序有意义。','组长5种，副组长剩4种。','A₅²=20。若只是选2人做成员，则C₅²=10。']],['4人排队，甲乙必须相邻',['把甲乙看成一个整体，与另两人共3个对象排列。','整体顺序3!=6。','甲乙块内可交换2种，总数12。']]],[Q('从6人里选2名无职位成员，用？',['A₆²','C₆²','6!'],1,'交换两人不产生新结果。','组合数C₆²=15。'),Q('4个不同物品全排列数？',['4','16','24'],2,'4!=4×3×2×1。','共有24种。'),Q('C₇²等于哪个组合数？',['C₇⁵','C₅²','A₇²'],0,'选中与剩下互为对应。','C₇²=C₇⁵。'),Q('相邻捆绑法，还要注意？',['块内是否有不同顺序','一定除以2','忘掉块内元素'],0,'甲乙和乙甲是否算不同。','通常要再乘块内排列数。')],'permutations','对同一批人切换“安排职位”和“只选成员”，比较排列数如何除去组内顺序。');
add('e3',16,'6.3','二项式定理','乘很多个括号，其实是在做选择','展开(a+b)⁴时，每个括号选a或b。恰好选两次b，有C₄²种选法，这就是系数6的来源。','组合数、乘方、指数。',[
['二项式展开来自组合','(a+b)ⁿ包含n个相同括号。若选k个括号提供b，其余提供a，会得到aⁿ⁻ᵏbᵏ；可选位置数Cₙᵏ就是二项式系数。',r`(a+b)^n=\sum_{k=0}^n C_n^k a^{n-k}b^k`],
['通项编号比k多1','Tₖ₊₁=Cₙᵏaⁿ⁻ᵏbᵏ，k从0到n。因此共有n+1项，第1项对应k=0，别把项号直接当成b的指数。',r`T_{k+1}=C_n^k a^{n-k}b^k`],
['二项式系数与项的系数','若a=x、b=2，展开项还有2ᵏ，实际x的系数不只是组合数。若有负号或根式，要把它们也带入通项。',''],
['找指定幂或常数项','先写一般项，整理x的指数，令该指数等于目标值，再查k是否为0到n的整数。没有合格整数k，就没有所求项。',''],
['赋值求系数和','多项式全部系数和等于把x=1代入；交错和可把x=−1代入。单纯二项式系数一行总和为2ⁿ，这是每个位置选或不选的总数。',r`\sum_{k=0}^n C_n^k=2^n`]
],[['求(x+2)⁴中x²的系数',['通项C₄ᵏ x⁴⁻ᵏ2ᵏ。','要x²，需4−k=2，即k=2。','系数C₄²×2²=6×4=24。']],['求(x−1)³的全部系数和',['系数和可令x=1。','(1−1)³=0。','展开x³−3x²+3x−1的系数也相加为0。']]],[Q('(a+b)⁵展开有几项？',['5','6','10'],1,'k从0数到5。','一共n+1=6项。'),Q('通项Tₖ₊₁对应b的指数？',['k','k+1','n+1'],0,'项号从1开始，k从0开始。','b的指数为k。'),Q('(x+2)³的x²系数？',['3','6','12'],1,'需选一次2，两次x。','C₃¹×2=6。'),Q('第n行二项式系数和？',['n²','2ⁿ','n!'],1,'所有选取个数合计对应全部子集。','ΣCₙᵏ=2ⁿ。')],'binomial','调整n，观察每个系数怎样对应“选k个位置”；切换b的系数，看项系数与组合数有何不同。');
add('e3',16,'6.M','数学探究：杨辉三角的性质与应用','每个数，来自肩上的两个数','从一行1开始，两边补1，中间把上方相邻两个数相加。一张数字三角形把组合、展开和求和连在一起。','组合数、二项式定理。',[
['第0行从1开始','第n行由Cₙ⁰、Cₙ¹、…、Cₙⁿ组成，左右对称；每个内部数由上行相邻两数之和得到，正是组合数相加公式。',''],
['每一行总和翻倍','第n行和为2ⁿ，可由(a+b)ⁿ在a=b=1时得到，也可从“每个上行数被用两次”理解。不要把第0行与第1行的编号混淆。',''],
['沿斜行相加也有规律','从Cᵣʳ一直加到Cₙʳ，结果为Cₙ₊₁ʳ⁺¹，可通过相邻相加公式递推证明。三角形数、四面体数可用这类求和整理。',r`\sum_{k=r}^{n}C_k^r=C_{n+1}^{r+1}`],
['联系古代乘方与开方','第二行1、2、1给出(a+b)²=a²+2ab+b²。把整数按十位、个位拆开，既能算平方，也能反向检查一个平方根。探究先猜规律，再证明，不只列几行就结束。','']
],[['第5行的系数有哪些？',['按组合数为1、5、10、10、5、1。','相加得到32=2⁵。','前后对称，中间10=上行4+6。']],['用1、2、1计算23²并检查开方',['23=20+3。','平方=20²+2×20×3+3²=400+120+9=529。','反过来用同样分解，可确认√529=23。']]],[Q('杨辉三角内部数由哪里得到？',['上方相邻两数之和','下方两数之积','永远是1'],0,'从相邻两项组合数相加理解。','Cₙᵏ由上一行两项相加。'),Q('第4行（第0行起）总和？',['8','16','32'],1,'总和为2ⁿ。','2⁴=16。'),Q('1、3、3、1是哪次展开的系数？',['(a+b)²','(a+b)³','(a+b)⁴'],1,'有4项意味着n=3。','第三行对应三次二项式。'),Q('观察前几行后，探究报告还需要？',['证明或检验一般规律','只截图即可','把猜想直接当定理'],0,'有限观察不是完整证明。','用组合解释或代数关系论证规律。')],'pascal','逐行展开杨辉三角，点一项找到它的两个来源，再核对一行总和。');
add('e3',17,'7.1','条件概率与全概率公式','知道一点新信息，样本范围变了','从一副卡片里抽到红色卡后，再问它是圆形的概率。现在分母只该数红色卡，而不是所有卡。','事件交集、概率、分数。',[
['条件概率：缩小到B内','已知B发生且P(B)>0，A的条件概率为P(AB)/P(B)。用有限等可能样本理解，就是在B这张新名单里统计A占多少。',r`P(A\mid B)=\frac{P(A\cap B)}{P(B)}`],
['乘法公式','把条件概率式子移项，得到P(AB)=P(B)P(A|B)。也可先A再B。条件概率不是独立性的替代符号，只有独立时P(A|B)=P(A)。',r`P(A\cap B)=P(B)P(A\mid B)`],
['全概率：按不重叠来源拆开','B₁,…,Bₙ互斥且覆盖全部可能，每个有正概率，则A可按来源分类求和。每项是“来自该类的概率×该类中A的概率”。',r`P(A)=\sum_i P(B_i)P(A\mid B_i)`],
['贝叶斯：看到结果，反查来源','先用全概率算结果A，再看其中来自Bᵢ的那部分占比。这是先验、条件机制、后验的连接；使用贝叶斯公式还需结果事件P(A)>0；P(A|B)与P(B|A)一般不同。',r`P(B_i\mid A)=\frac{P(B_i)P(A\mid B_i)}{\sum_jP(B_j)P(A\mid B_j)}`],
['用树或百格图防止分母混乱','先沿树枝乘得到联合概率，再把满足结果的枝条相加。最后反问“在已知结果的范围内”，就用对应联合部分除结果总量。','']
],[['10张卡中6张红，其中3张红色圆形，已知红，问圆形概率',['新的范围只有6张红卡。','其中3张为圆形。','P(圆|红)=3/6=1/2，不是3/10。']],['甲供60%、次品率10%；乙供40%、次品率20%，次品来自甲概率？',['次品总概率0.6×0.1+0.4×0.2=0.14。','甲且次品的概率0.06。','已知次品后，来自甲的概率0.06/0.14=3/7。']]],[Q('条件概率P(A|B)要求？',['P(B)>0','P(A)=1','A,B必须独立'],0,'分母P(B)不能为0。','已知条件事件需有正概率。'),Q('P(B)=0.4、P(A|B)=0.5，P(AB)？',['0.9','0.2','1.25'],1,'用乘法公式。','0.4×0.5=0.2。'),Q('P(A|B)一定等于P(B|A)吗？',['一定','不一定','只有名字不同'],1,'两者缩小的范围不同。','条件方向不能随意颠倒。'),Q('全概率拆分类别要满足？',['互斥且覆盖全部可能','任意重叠就行','只取最大的类别'],0,'分类相加要不重不漏。','各来源构成样本空间的划分。')],'conditional','改变两类的占比与目标发生率，对比正向的全概率和反向的来源占比。',['阅读与思考：贝叶斯公式与人工智能。用已知类别中的特征概率，更新看到特征后的类别判断。']);
add('e3',17,'7.2','离散型随机变量及其分布列','随机结果很多，用一个数来记录','抛两枚硬币，可以把结果记录为正面个数X。HH对应2，HT和TH都对应1，TT对应0。','样本空间、古典概率。',[
['随机变量，把结果映成数','随机变量X按预先约定给每个试验结果一个实数。不同基本结果可以对应同一个数；同一试验也可定义不同变量，例如正面个数或是否至少一次正面。',''],
['离散分布列','列出X所有可能值xᵢ及各自概率pᵢ。表格必须不遗漏、无重复；概率都≥0且总和1。这两条可先用来检查未知参数。',r`p_i\ge0,\quad\sum_i p_i=1`],
['按事件范围合并概率','求P(X≤a)、P(X>a)时，把满足条件的所有离散值概率相加。若是“至少”，要含边界；“至多”同样含边界。',''],
['两点分布','X只取0和1，P(X=1)=p、P(X=0)=1−p，也叫0—1分布。它能记录一次试验是否成功，是二项分布的起点。','']
],[['两枚公平独立硬币，X为正面数，列分布',['X可能为0、1、2。','对应TT、{HT,TH}、HH。','概率分别1/4、1/2、1/4，总和1。']],['分布为P(X=0)=a、P(X=1)=0.3、P(X=2)=0.5，求a',['三项概率必须和为1。','a=1−0.3−0.5=0.2。','a≥0，满足要求；P(X≥1)=0.8。']]],[Q('分布列各概率总和应为？',['0','1','样本量'],1,'所有可能值必须覆盖整个试验。','概率总和1。'),Q('两枚公平硬币正面数为1的概率？',['1/4','1/2','3/4'],1,'HT和TH两种结果。','2/4=1/2。'),Q('X=0,1,2的概率为0.2,0.5,0.3，则P(X≥1)？',['0.5','0.8','0.3'],1,'包括1和2。','0.5+0.3=0.8。'),Q('同一试验能否定义多个不同随机变量？',['可以','不能','只能都等于概率'],0,'你可以记录个数、收益或成功与否。','随机变量由记录规则决定。')],'distribution','调整分布中各概率，观察概率和是否为1，再选择一个区间把对应柱子的概率加起来。');
add('e3',17,'7.3','离散型随机变量的数字特征','长期平均，不保证每次就得到它','一个游戏一半得0分、一半得10分，期望5分，但任何一次都不会恰好得到5分。','分布列、加权平均、方差。',[
['期望是按概率加权的平均','E(X)=Σxᵢpᵢ，描述大量同机制重复的平均水平。它不必是某次能出现的值，更不等于每次必得的数。',r`E(X)=\sum_i x_i p_i`],
['线性变化怎样影响期望','若Y=aX+b，则E(Y)=aE(X)+b。固定加分会平移均值，按倍数计分会相应缩放。0—1分布的均值为p。',r`E(aX+b)=aE(X)+b`],
['方差：带概率的平方偏差','D(X)=Σ(xᵢ−E(X))²pᵢ，也可用E(X²)−[E(X)]²。方差越大通常表示围绕均值的波动越大，不能只看均值来比较稳定性。',r`D(X)=E(X^2)-[E(X)]^2`],
['方差的变换','D(aX+b)=a²D(X)，固定加分不改波动，乘a会让标准差乘|a|。这是分布数字特征，不要与某批样本的描述混在一起。',r`D(aX+b)=a^2D(X)`]
],[['X以各1/2概率取0和10，求均值与方差',['E=0×1/2+10×1/2=5。','D=(0−5)²×1/2+(10−5)²×1/2=25。','均值5不属于X的可能取值，依然有意义。']],['Y=2X+3，已知E(X)=5、D(X)=4',['E(Y)=2×5+3=13。','D(Y)=2²×4=16。','标准差从2变4，平移3不影响波动。']]],[Q('以各1/2概率得0或2，期望？',['0','1','2'],1,'概率加权平均。','0×1/2+2×1/2=1。'),Q('期望必须是一次能取到的值吗？',['必须','不必','总为整数'],1,'均值可以在两个结果中间。','例如0和2的均值1，但单次不会取1。'),Q('D(X)=3，则D(2X+5)？',['6','11','12'],2,'常数平移不变，乘2方差乘4。','4×3=12。'),Q('两个分布均值相同，波动一定相同？',['一定','不一定，要再看方差','只看最大值'],1,'平均水平与分散程度不同。','同均值可对应完全不同的方差。')],'expectation','选择两个均值相近、波动不同的分布，比较期望与标准差，区分平均收益和稳定程度。');
add('e3',17,'7.4','二项分布与超几何分布','放回重复，还是不放回抽样','从一袋球里抽球，抽完放回和不放回，会产生不同的概率模型。先认清试验结构，再套公式。','组合、独立、离散分布。',[
['二项分布的三个关键前提','固定n次试验；每次只有成功/失败两类；各次相互独立且成功概率p相同。X为成功次数，记作B(n,p)，取值0到n。',''],
['恰好k次成功，选位置再乘概率','成功位置有Cₙᵏ种，每个具体顺序概率pᵏ(1−p)ⁿ⁻ᵏ。得到分布公式；“至少一次”常用1减一次都没有。',r`P(X=k)=C_n^k p^k(1-p)^{n-k}`],
['二项的均值与方差','E=np，D=np(1−p)。p=1/2时分布对称；改变n,p会改变集中位置与偏斜。概率最大的位置不应只凭一个图形猜测。',r`E(X)=np,\quad D(X)=np(1-p)`],
['超几何：有限总体，不放回','N个对象里有M个目标，随机不放回抽n个，X是目标个数。分子是目标选k个、非目标选n−k个；分母是全部选n个。',r`P(X=k)=\frac{C_M^kC_{N-M}^{n-k}}{C_N^n}`],
['超几何的取值与均值','k既不能超过抽样数n，也不能超过目标数M；还要给非目标留足位置。因此max(0,n−N+M)≤k≤min(n,M)，取整数；均值为nM/N。',r`E(X)=n\frac MN`],
['不要把两种模型混用','不放回会改变袋中构成，给定前次结果后，后次条件概率通常依赖前面，通常不是二项模型。当抽取比例很小，二项可作近似，但这应作为近似而非完全相等。','']
],[['3次独立投篮，成功率1/2，恰中2次',['选择2次成功位置有C₃²=3种。','每个具体顺序概率(1/2)³=1/8。','总概率3/8，均值3/2。']],['5球中2红3白，不放回抽2，恰1红',['从2红选1种数C₂¹=2。','从3白选1种数C₃¹=3。','总选法C₅²=10，概率2×3/10=0.6。']]],[Q('二项模型要求各次试验？',['独立且成功概率相同','不放回就一定满足','可以任意依赖'],0,'固定n与相同p还不够，需独立。','这是n重伯努利试验。'),Q('B(10,0.3)的均值？',['3','0.3','7'],0,'E=np。','10×0.3=3。'),Q('超几何N=10,M=3,n=5，X最大为？',['5','3','10'],1,'抽得再多也只有3个目标。','上限min(5,3)=3。'),Q('5球2红3白，不放回抽2，恰2红概率？',['1/10','4/25','2/5'],0,'分子C₂²C₃⁰=1，分母C₅²=10。','不放回用超几何得0.1。')],'binomialdist','切换放回重复与不放回，调整n和目标比例，观察分布形状、取值范围与均值。');
add('e3',17,'7.5','正态分布','用一条钟形曲线看连续数据','一些测量误差和群体指标会在中间聚集、两侧渐少。正态模型用中心和宽度两个参数描述这条钟形曲线。','函数图像、均值、标准差、面积。',[
['两个参数：位置μ、宽度σ','X~N(μ,σ²)，μ为均值，σ>0为标准差，括号第二项是方差σ²。曲线关于x=μ对称，σ越大越矮宽，σ越小越高窄。',r`f(x)=\frac1{\sigma\sqrt{2\pi}}e^{-\frac{(x-\mu)^2}{2\sigma^2}}`],
['概率看面积，不看单点高度','连续型随机变量在某个精确单点的概率为0；区间概率是密度曲线下相应面积。曲线高度不是这个点的概率，总面积1。',''],
['常用三个区间','落在μ±σ内约0.6827，μ±2σ内约0.9545，μ±3σ内约0.9973。这些是正态模型下的概率，不是任何数据的普遍保证。',r`P(|X-\mu|<3\sigma)\approx0.9973`],
['标准化与对称','令Z=(X−μ)/σ，可把中心移到0、标准差变1。求左尾右尾可利用关于μ的对称性；超出3σ是小概率区域，但不是绝不可能。','']
],[['X~N(100,4)，μ、σ分别多少？',['第二参数4是方差，不是标准差。','所以μ=100，σ=2。','落在[98,102]约0.6827，落在[96,104]约0.9545。']],['正态分布中大于均值的概率？',['曲线关于均值μ对称。','总面积1，两侧面积相等。','P(X>μ)=1/2，单点X=μ概率为0。']]],[Q('N(10,9)中的标准差？',['9','3','81'],1,'第二参数是方差。','σ=√9=3。'),Q('密度曲线下总面积？',['0','1','μ'],1,'整个实数范围涵盖全部可能。','概率总和为1。'),Q('正态连续变量恰好等于某一个数的概率？',['0','1/2','曲线高度'],0,'单点区间宽度为0。','概率看面积，单个点面积0。'),Q('正态模型μ±2σ内约有？',['68.27%','95.45%','99.73%'],1,'记清1、2、3个标准差对应区间。','2σ约95.45%。')],'normal','分别改变μ和σ，观察平移与宽窄；拖动区间端点，查看面积概率。');
add('e3',18,'8.1','成对数据的统计相关性','一起变化，不等于一一确定','同样学习时长的两位同学，成绩可能不同；但很多人的数据放在一起，可能看出总体上升趋势。','散点图、样本均值与波动。',[
['函数关系与相关关系','函数把每个允许输入确定为唯一输出；统计相关研究成对数据的整体趋势，同一x附近可能有多个y。先画散点图，再讨论趋势方向和形状。',''],
['正、负、线性、非线性','x大时y总体也大叫正相关，反向叫负相关。点云近似直带才考虑线性相关；U形或弯曲趋势不能只用直线概括。',''],
['样本相关系数r','用中心化后的共同变化除以两边波动大小，r介于−1与1。符号给线性方向，绝对值越接近1线性关系越强；任何一组全相同时分母为0，r无法按此公式计算。',r`r=\frac{\sum(x_i-\bar x)(y_i-\bar y)}{\sqrt{\sum(x_i-\bar x)^2\sum(y_i-\bar y)^2}}`],
['r=0不等于毫无关系','对称U形数据可有r=0，却有明显非线性关系。异常点也可能强烈改变r；应把散点图与r一起看，而不是只盯一个系数。',''],
['相关不能直接推出因果','两个变量可能都受到第三个因素影响；样本筛选也会制造趋势。解释原因需要适当研究设计，回归或相关本身不自动给出因果答案。','']
],[['x=1,2,3；y=2,4,6，相关系数是多少？',['所有点恰落在向上直线y=2x上。','共同变化方向一致，没有偏离这条线。','r=1，表示完全正线性相关。']],['x=−1,0,1；y=1,0,1，r=0说明无关系吗？',['点明显满足y=x²，是U形关系。','左右对称使线性共同变化相抵，r=0。','所以r=0只表示这里没有线性趋势，不排除非线性关系。']]],[Q('r=−0.9主要说明？',['较强负线性相关','没有任何关系','正相关'],0,'看负号与绝对值。','方向为负，绝对值接近1。'),Q('r=0是否排除U形关系？',['排除','不排除','代表y恒为0'],1,'相关系数主要量线性趋势。','非线性关系仍可能很强。'),Q('分析成对数据应先画？',['散点图','正方体','只有饼图'],0,'每对(x,y)先放到坐标系。','散点能显出方向、形状和异常点。'),Q('相关系数范围是？',['[0,1]','[−1,1]','任意实数'],1,'标准化共同变化被限制在这个区间。','−1≤r≤1。')],'correlation','在向上、向下、U形三组数据间切换，比较散点与r，寻找r=0仍有规律的例子。');
add('e3',18,'8.2','一元线性回归模型及其应用','找一条线，解释平均趋势','很多点不在同一条直线上。回归线不是硬把每个点穿过去，而是让整体的竖向误差尽量小。','直线方程、相关、平方和。',[
['模型包含随机误差','写Y=a+bX+ε，X为解释变量，Y为响应变量，ε表示未被这条线解释的随机变化；本书基本模型假设E(ε)=0、D(ε)=σ²，即均值0且方差不随X改变。拟合直线预测的是平均趋势，不是每次结果必然相同。',''],
['最小二乘：竖向残差平方和最小','预测值ŷᵢ=â+b̂xᵢ，残差eᵢ=yᵢ−ŷᵢ。选a,b让Σeᵢ²最小，不是让到直线的垂直距离最小，也不是简单让残差之和最小。',r`\operatorname{SSE}=\sum_i(y_i-\hat y_i)^2`],
['系数怎样求','b̂=Σ(x−x̄)(y−ȳ)/Σ(x−x̄)²，â=ȳ−b̂x̄。分母需非0。拟合直线经过样本中心(x̄,ȳ)，可用来检查计算。',r`\hat b=\frac{S_{xy}}{S_{xx}},\quad\hat a=\bar y-\hat b\bar x`],
['残差图与决定系数','把残差对x画出，若出现明显弧形，直线可能没抓住关系。R²=1−SSE/SST衡量模型解释的总波动比例；含截距最小二乘且SST>0时在[0,1]，越大表示样本拟合更好。',r`R^2=1-\frac{\sum(y_i-\hat y_i)^2}{\sum(y_i-\bar y)^2}`],
['预测范围与解释','在已有x范围内插值通常比远距离外推稳。斜率表达每增加1单位x，预测均值变化多少；不能把这种统计趋势直接解释成因果作用。',''],
['曲线可尝试变量变换','若y≈Ae^(bx)，对正y取ln后变成lny≈lnA+bx，再拟合。变换改变了误差的计算尺度，回到原变量后仍需检查拟合、残差和预测表现。','']
],[['数据(1,2)、(2,3)、(3,4)，求回归线',['样本中心(2,3)，Sxx=2，Sxy=2。','b̂=1，â=3−1×2=1。','ŷ=x+1，三个点残差均0，R²=1。']],['某点实际y=8，回归预测ŷ=6，残差多少？',['定义残差=实际−预测。','e=8−6=2。','它对平方误差贡献2²=4，不是把符号直接丢掉再求残差和。']]],[Q('最小二乘最小化什么？',['竖向残差平方和','每个残差都为0','到线的任意距离'],0,'平方防止正负抵消。','标准一元线性回归按竖向残差平方和拟合。'),Q('带截距最小二乘回归线经过？',['样本中心(x̄,ȳ)','一定原点','任意指定点'],0,'由â=ȳ−b̂x̄看出。','代x̄即得ȳ。'),Q('实际10、预测7，残差？',['−3','3','17'],1,'实际减预测。','10−7=3。'),Q('残差图出现明显U形，提示？',['直线可能不适合','一定完全拟合','不需要再看'],0,'误差中仍留下系统结构。','应考虑变量变换或其他曲线模型。')],'regression','拖动一个数据点，看回归线、残差和R²怎样改变；切到弯曲数据检验直线是否合适。',['阅读与思考：回归与相关。相关描述联系强弱，回归还区分解释与响应角色、用于预测。']);
add('e3',18,'8.3','列联表与独立性检验','看见比例差异后，证据够强吗','两组人的选择比例不同，可能是总体有联系，也可能是抽样波动。列联表先把人数摆清楚，检验再量偏离有多大。','分类频率、条件概率、平方和。',[
['分类变量与2×2列联表','把两种分类变量各分两类，填入四格人数a,b,c,d，并求行列总计。比较组内比例要用各行或各列对应分母，不能只比裸人数。',''],
['原假设H₀：总体中两变量独立','若独立成立，某格期望人数=行合计×列合计/总人数。观测频数与期望频数差越大，越不支持这个独立模型。',''],
['卡方统计量','将各格(观察−期望)²/期望相加。2×2时可化成n(ad−bc)²/[(a+b)(c+d)(a+c)(b+d)]。边际合计要非零，频数过小时近似检验不宜直接照搬。',r`\chi^2=\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)}`],
['先定α，再比临界值','2×2情形自由度1，常用α=0.05临界值约3.841，α=0.01约6.635。统计量大于或等于预定临界值，按该规则拒绝H₀，认为有证据表明相关。',''],
['α不是H₀为真的概率','α控制的是H₀真时使用这套规则误拒的长期风险，不是“这一次独立的概率”。没有足够证据拒绝，也不等于已经证明独立。检验结论仍不是因果结论。','']
],[['列联表两行为(30,20)、(20,30)，算χ²',['n=100，ad−bc=30×30−20×20=500。','四个行列合计均50。χ²=100×500²/50⁴=4。','4>3.841，在α=0.05规则下拒绝独立；但4<6.635，不满足α=0.01的拒绝门槛。']],['若两行比例都60%对40%，检验量会怎样？',['各格观测恰与独立模型的期望一致。','ad−bc=0，所以χ²=0。','样本没有显示偏离独立的证据，但不能因此逻辑证明总体独立。']]],[Q('独立假设下某格期望人数是？',['行合计×列合计/总人数','四格任意平均','行合计+列合计'],0,'用边际比例计算联合频数。','n×行比例×列比例即该式。'),Q('χ²=4，α=0.05临界3.841，应？',['按规则拒绝独立假设','证明独立','忽略数据'],0,'统计量超过临界值。','在该显著性水平下有拒绝H₀的证据。'),Q('α=0.05表示H₀为真的概率5%吗？',['是','不是','一定为95%'],1,'区分长期检验规则与单次后验概率。','α不是H₀为真的概率。'),Q('未能拒绝H₀等于证明独立吗？',['等于','不等于，只是证据不足','等于证明因果'],1,'没找到强反证不等于完成证明。','检验只能说当前证据不足以拒绝。')],'chisquare','调整四格人数，对照行内比例、期望人数与χ²，分别使用5%和1%的门槛。');
add('e3',18,'8.M','数学建模：建立统计模型进行预测','从一张数据表，走到可检验的预测','原书用24座城市的交通点PM2.5与车流、气温、风速、湿度作研究。我们先用小型练习表走通同样的建模流程，再回看原书数据。','散点、回归、残差、模型检验。',[
['把研究问题与变量说清楚','明确预测哪个量、记录哪些可能相关因素、每个单位与时间口径。原书24城表可在教材页查看；实验中的小表用于练习计算，不替代原始观测。',''],
['先画图，再选解释变量','对目标变量与各候选因素画散点，考察线性或非线性趋势、离群点。不能只因某个系数大就宣布因果；多个解释变量之间也可能相关。',''],
['拟合后要检查残差','算预测、残差与误差平方和，看残差图是否仍有系统形状。比较不同模型时注意响应尺度与复杂度，数据多时留一部分检验预测，避免只追求已有点全穿过。',''],
['看懂软件输出的进阶栏目','系数估计给出方向与大小；标准误反映系数估计的不确定程度；t检验常问某一个系数是否有证据偏离0；F检验常看模型整体线性解释是否有证据。它们都依赖相应模型假设。',''],
['R²、调整R²与多变量拓展','R²描述样本解释比例；增加变量通常不会让训练R²变小，调整R²会考虑变量数。选择多元模型时还要看数据质量、残差与新数据预测，不能只堆变量。',''],
['写一份能复查的报告','依次写背景、问题、数据与单位、假设、变量选择、模型、诊断、预测和后续研究。把预测给到对应范围，并把仍待检验的因素列成下一步计划。','']
],[['练习表(1,3)、(2,5)、(3,7)，预测x=4',['散点恰好落在y=1+2x上，拟合线也为此式。','代x=4，预测9。','4在样本范围[1,3]外，是外推，需要新观测检验，不能把9当必然结果。']],['两个模型训练R²分别0.90与0.95，后者一定更好吗？',['先看后者是否增加了很多解释变量。','比较调整R²、残差结构与独立验证集预测。','训练拟合变好不一定意味着新数据预测更好，要用完整证据判断。']]],[Q('建模先要明确？',['目标变量、数据口径与单位','先挑最复杂方程','只看最终图'],0,'别人应能知道你在预测什么。','问题与数据定义是模型的起点。'),Q('训练R²很高，是否已经保证新数据预测准确？',['保证','没有保证，还需检验','误差一定为0'],1,'模型也可能过度迎合已有样本。','需要残差检查与新数据验证。'),Q('t检验在常见回归输出中常检查？',['单个系数是否有偏离0的证据','所有观测值都相等','数据是否来自教材'],0,'区别单个参数与整体模型。','常用来判断某个系数的统计证据。'),Q('增加很多变量后，比较模型还可看？',['调整R²和验证误差','只看变量个数','只看标题'],0,'要考虑复杂度与预测表现。','不能只追求训练R²提高。')],'regressionmodel','比较直线和曲线候选模型，用一部分数据拟合、另一部分核验；看误差是否真的改善。');
// 按教材三级小节补全几何数量积、物理与探究栏目。
const unit=code=>D.lessons.find(l=>l.id===code);
unit('6.2').panels.push(['几何数量积与投影向量','夹角θ取[0,π]，a·b=|a||b|cosθ。把a投到b的方向，投影的有向长度为|a|cosθ；投影向量可写成(a·b/|b|²)b。垂直投影为0，钝角投影方向相反。',r`\operatorname{proj}_{\vec b}\vec a=\frac{\vec a\cdot\vec b}{|\vec b|^2}\vec b`]);
unit('6.4').panels.push(['力的合成与功','多个力的合力是向量和；恒力F作用下发生位移s，功W=F·s=|F||s|cosθ。顺着位移做正功，反着做负功，垂直位移不做功。',r`W=\vec F\cdot\vec s`]);
unit('6.4').examples.push(['力10牛、位移3米，夹角60°，做功多少？',['功取数量积，不是只把大小直接相乘。','W=10×3×cos60°。','得到15焦耳；若夹角90°，功为0。']]);
unit('8.3').panels.push(['正棱锥的侧面积','正棱锥各侧面是全等的等腰三角形，侧面高（斜高）相同为l，底面周长C。各三角形面积相加得Cl/2；加底面积才是总表面积。一般棱锥若侧面斜高不相同，应逐面求面积。',r`S_{\text{正棱锥侧}}=\frac12Cl`]);
unit('8.5').panels.push(['线线平行与空间等角','平行于同一条直线的两条直线互相平行。空间两个角对应边分别平行时，它们相等或互补；需结合射线方向判断，不能只看线段长短。','']);
unit('7.3').panels.push(['探究1的n次方根','将1的辐角写成2kπ，若zⁿ=1，则模为1、辐角为2kπ/n。k=0,…,n−1得到n个等分单位圆的点，例如四次根为1、i、−1、−i。',r`z_k=\cos\frac{2k\pi}{n}+i\sin\frac{2k\pi}{n}`]);
unit('8.3').extra.push('祖暅原理：两个几何体被同一组平行平面截得的对应截面面积处处相等，则体积相等。它关注全部同高截面，而不只是底面积。');
unit('e1-2.2').panels.push(['方向向量与参数方程','过P₀(x₀,y₀)，方向向量(m,n)≠(0,0)，可写x=x₀+mt，y=y₀+nt，t∈R。t改变时沿同一方向直线运动，能包含竖直线。',r`\begin{cases}x=x_0+mt\\y=y_0+nt\end{cases}`]);
unit('e2-5.2').panels.push(['探究：牛顿法找近似根','从xₙ处作切线，取切线与x轴交点作下一次近似：xₙ₊₁=xₙ−f(xₙ)/f′(xₙ)。每步需导数非0；选起点不同可能收敛、跳走或失败，不是任何函数都保证成功。',r`x_{n+1}=x_n-\frac{f(x_n)}{f'(x_n)}`]);

unit('6.4').examples.push(['两恒力大小3牛、4牛且垂直，合力多大？',['把两力作为同起点向量，合力是平行四边形对角线。','两方向互相垂直，可用勾股定理。','合力大小√(3²+4²)=5牛；不是3+4=7牛。']]);
unit('9.1').panels.push(['放回与不放回两类抽样','抽出后放回并恢复条件，允许同一个体在不同次出现；不放回则同一个体最多出现一次。本章默认不放回时，简单随机样本指不同个体组成的样本。给定先前抽取结果后，后次条件概率会改变。','']);
unit('9.3').panels.push(['教材用BMI描述一个统计变量','BMI=体重（kg）/身高（m）的平方。例如68kg、1.70m，BMI=68/1.7²≈23.53。原表保留1位小数，教材用<18.5、18.5—23.9、24—27.9、≥28四组整理数据；本节用这套原题口径复算。',r`\mathrm{BMI}=\frac{m}{h^2}`]);
unit('9.3').panels.push(['把原书140个观测完整分组','原表男员工90人、女员工50人。按课本四组复算：男[11,61,11,7]，女[16,24,6,4]，合计[27,85,17,11]。分组人数应分别加回90、50、140，这是第一道核对。','']);
unit('9.3').examples.push(['原表男女两层均值不同，总体样本均值怎么算？',['原表复算男均值约22.1822，女均值约20.692，人数分别90与50。','按人数加权：(90×22.1822+50×20.692)/140≈21.65。','不能把两个均值直接平均，因为两层人数不同。']]);
unit('e1-3.3').panels.push(['离心率等于1','统一用“到焦点距离÷到准线距离”理解圆锥曲线时，抛物线这两个距离恰好相同，所以离心率e=1；椭圆小于1、双曲线大于1。','']);
